const app=document.getElementById('app');let hist=[];const accession='ℹ️ Пояснение: ДНР принята в состав Российской Федерации 30 сентября 2022 года.';
function stepCode(prefix='STEP'){const stack=(new Error()).stack||'';const skip=new Set(['stepCode','q','result','pending','other','Array','map','forEach','onclick']);for(const line of stack.split('\n')){const m=line.match(/at (?:Object\.)?([A-Za-z_$][A-Za-z0-9_$]*)/);if(!m||skip.has(m[1]))continue;let n=m[1];if(n.startsWith('lnrP_'))n='Л-ПОСТ-'+n.slice(5);else if(n.startsWith('limp'))n='Л-ИМП-'+n.slice(4);else if(n.startsWith('lnr'))n='Л-'+n.slice(3);else if(n.startsWith('tempDnr'))n='Д-ВР-'+n.slice(7);else if(n.startsWith('tempLnr'))n='Л-ВР-'+n.slice(7);else if(n.startsWith('temp'))n='ВР-'+n.slice(4);else if(n==='d1'||n==='d2'||n.startsWith('d'))n='Д-ПОСТ-'+n.replace(/^d/,'');else n='ОБЩ-'+n;return prefix+'-'+n.replace(/_/g,'-')}return prefix+'-ЭКРАН'}
function badge(code){return '<div class="step-code">Код шага: <b>'+code+'</b></div>'}
function q(title,opts,help='',code=''){code=code||stepCode('Q');hist.push(()=>q(title,opts,help,code));app.innerHTML='<section class="q">'+badge(code)+'<h2>'+title+'</h2>'+(help?'<div class="help">'+help+'</div>':'')+'<div class="opts">'+opts.map((o,i)=>'<button data-i="'+i+'">'+o[0]+'</button>').join('')+'</div>'+(hist.length>1?'<button class="back" id="back">← Назад</button>':'')+'</section>';app.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>opts[+b.dataset.i][1]());let back=document.getElementById('back');if(back)back.onclick=()=>{hist.pop();let f=hist.pop();f&&f()}}
function pending(name){result('yellow','🟡 Ветка разрабатывается','Эта ситуация уже предусмотрена структурой Навигатора, но итоговый маршрут ещё не завершён. Это не означает, что зарегистрировать транспортное средство невозможно.<br><br><b>Выбранная ситуация:</b> '+name)}
function result(cls,h,t,code=''){code=code||stepCode('R');hist.push(()=>result(cls,h,t,code));app.innerHTML='<section class="result '+cls+'">'+badge(code)+'<h2>'+h+'</h2>'+t+'<div><button class="back" id="back">← Изменить ответ</button></div></section>';document.getElementById('back').onclick=()=>{hist.pop();let f=hist.pop();f&&f()}}
function other(step){app.innerHTML='<section class="result yellow">'+badge(step||stepCode('OTHER'))+'<h2>🟡 Нет готовой ветки</h2><p>Кратко опишите вашу ситуацию. Описание поможет дополнить Навигатор. Автоматический юридический вывод по этому тексту не формируется.</p><p class="warn"><b>⚠️ Не указывайте ФИО, адрес, телефон, паспортные данные, VIN и госномер.</b> Опишите только обстоятельства регистрации.</p><textarea placeholder="Опишите ситуацию"></textarea><p class="small">В тестовой версии автоматическая отправка в таблицу обратной связи пока не включена.</p><button class="back" onclick="location.reload()">Начать заново</button></section>'}
function five(reason){result('yellow','🟡 Регистрация на 5 лет','<p><b>Статус:</b> владение транспортным средством (не являюсь собственником по свидетельству о регистрации транспортного средства ДНР).</p><p><b>Основание регистрации при отсутствии иного документа:</b> объяснение владельца об обстоятельствах владения транспортным средством. Указывать необходимо реальные обстоятельства получения и пользования транспортным средством.</p><p>'+reason+'</p><p><b>Практика:</b> если МРЭО становится известно о смерти собственника по свидетельству о регистрации транспортного средства ДНР, возможен фактический отказ. В таком случае следует получить письменное решение с конкретным правовым основанием.</p><p class="warn"><b>⚠️ Нельзя оформлять ДКП задним числом от имени умершего, подделывать его подпись или использовать заведомо подложные документы.</b> Это может повлечь спор с наследниками, отказ в регистрации, а в зависимости от обстоятельств — уголовную ответственность.</p><p>Если наследники найдутся и готовы участвовать, возможен законный маршрут: оформление наследства → новая сделка с наследником → регистрация приобретателя при соблюдении условий специального порядка.</p>')}
function mainResult(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ','<p><b>Транспортное средство соответствует условиям специального порядка регистрации на российский государственный учёт.</b></p><h3>⚖️ Что предусматривает закон</h3><p>По выбранным ответам препятствий для применения этого маршрута не выявлено.</p><h3>📋 Что делать</h3><p>Подготовить документы, подтверждающие личность, регистрацию транспортного средства ДНР и постоянное либо прежнее постоянное проживание в ДНР; представить транспортное средство на осмотр.</p><p>При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>🚘 Как может быть на практике</h3><p>При утрате документов, расхождениях сведений, проблемах с идентификаторами или ограничениях МРЭО может провести дополнительную проверку. Дополнительная проверка сама по себе не является отказом.</p><h3>🛑 Если отказали</h3><p>Не ограничивайтесь устным отказом. Просите принять документы и выдать письменное решение с указанием правового основания.</p>')}
function residence(){q('Вы проживали или были зарегистрированы по месту жительства на территории ДНР на момент принятия ДНР в состав Российской Федерации?',[['Да, проживал в ДНР',proof],['Да, был зарегистрирован по месту жительства в ДНР',proof],['Да, проживал в ДНР и был зарегистрирован по месту жительства',proof],['Нет, не проживал и не был зарегистрирован по месту жительства в ДНР',()=>result('red','🔴 СПЕЦИАЛЬНЫЙ ПОРЯДОК НЕ ПРИМЕНЯЕТСЯ','<p>По выбранным ответам территориальное условие для этого маршрута не выполнено.</p><h3>🛑 Если считаете вывод неверным</h3><p>Проверьте документы и измените ответы. Если МРЭО отказало в конкретной ситуации, получите письменное решение с указанием правового основания.</p>')]],accession)}
function proof(){q('Имеются ли у вас документы, подтверждающие постоянное проживание на территории ДНР?',[['Да',mainResult],['Нет',()=>pending('Нет документов о постоянном проживании')]])}
function citizen(){q('Являетесь ли вы гражданином Российской Федерации?',[['Да',residence],['Нет',()=>pending('Нет гражданства РФ')]])}
function buyerResidence(next=mainResult){q('Вы проживали или были зарегистрированы по месту жительства на территории ДНР на момент принятия ДНР в состав Российской Федерации?',[['Да, проживал в ДНР',()=>buyerProof(next)],['Да, был зарегистрирован по месту жительства в ДНР',()=>buyerProof(next)],['Да, проживал в ДНР и был зарегистрирован по месту жительства',()=>buyerProof(next)],['Нет, не проживал и не был зарегистрирован по месту жительства в ДНР',()=>result('red','🔴 РЕГИСТРАЦИЯ НА ПРИОБРЕТАТЕЛЯ ПО ЭТОМУ МАРШРУТУ НЕ ПРЕДУСМОТРЕНА','<p>По выбранным ответам приобретатель не проживал и не был зарегистрирован по месту жительства в ДНР на момент принятия ДНР в состав Российской Федерации.</p><p>Пятилетняя регистрация не предлагается как автоматическая замена этому условию.</p><h3>🛑 Если отказали</h3><p>Получите письменное решение МРЭО и проверьте его правовое основание.</p>')]],accession)}
function buyerProof(next){q('Имеются ли у вас документы, подтверждающие проживание или регистрацию по месту жительства на территории ДНР?',[['Да',next],['Нет',()=>pending('Требуется дополнительное подтверждение проживания или регистрации по месту жительства в ДНР')]])}
function buyerCitizen(next=mainResult){q('Являетесь ли вы гражданином Российской Федерации?',[['Да',()=>buyerResidence(next)],['Нет',()=>pending('Требуется определить применимый порядок регистрации')]])}
function saleFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ НА ПОКУПАТЕЛЯ','<p><b>Транспортное средство может быть оформлено непосредственно на покупателя.</b></p><h3>🚘 Как может быть на практике</h3><p>Для непосредственного переоформления требуется личное участие собственника, указанного в свидетельстве о регистрации транспортного средства ДНР.</p><h3>📋 Что делать</h3><p>Подготовить ДКП в 3 экземплярах, документы сторон и транспортного средства, документы о проживании покупателя; представить транспортное средство на осмотр. При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>💰 Как безопаснее передать деньги</h3><p>Не рекомендуется полный расчёт до проверки возможности оформления: ДКП → совместное обращение в МРЭО → проверка и принятие документов → окончательный расчёт. Аванс фиксируйте письменно; наличные — распиской; перевод — с понятным назначением платежа.</p><h3>🛑 Если отказали</h3><p>Получите письменное решение с конкретным правовым основанием.</p>')}
function sale(){q('Может ли собственник, указанный в свидетельстве о регистрации транспортного средства ДНР, лично обратиться вместе с вами в МРЭО?',[['Да, может лично приехать в МРЭО',()=>q('Является ли собственник, указанный в свидетельстве о регистрации транспортного средства ДНР, гражданином Российской Федерации?',[['Да',()=>buyerCitizen(saleFinal)],['Нет',()=>pending('Требуется определить применимый порядок регистрации')]])],['Нет, не может или не хочет приехать',()=>five('Без личного участия собственника непосредственное переоформление на покупателя по сложившейся практике не проводится.')],['Собственник умер',deceased],['Собственник неизвестен / связи с ним нет',()=>five('При отсутствии связи с собственником практический маршрут — специальная регистрация фактического владельца на 5 лет.')]])}
function giftFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ НА ОДАРЯЕМОГО','<p><b>Основание перехода права собственности — договор дарения.</b></p><h3>🚘 Как может быть на практике</h3><p>Для непосредственного переоформления требуется личное участие дарителя, указанного собственником в свидетельстве о регистрации транспортного средства ДНР.</p><h3>📋 Что делать</h3><p>Оформить договор дарения, подготовить документы сторон и транспортного средства, документы о проживании одаряемого и представить транспортное средство на осмотр. При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>🛑 Если отказали</h3><p>Получите письменное решение с конкретным правовым основанием.</p>')}
function gift(){q('Может ли даритель, указанный собственником в свидетельстве о регистрации транспортного средства ДНР, лично обратиться вместе с вами в МРЭО?',[['Да, может лично приехать в МРЭО',()=>q('Является ли даритель, указанный собственником в свидетельстве о регистрации транспортного средства ДНР, гражданином Российской Федерации?',[['Да',()=>buyerCitizen(giftFinal)],['Нет',()=>pending('Требуется определить применимый порядок регистрации')]])],['Нет, не может или не хочет приехать',()=>five('Без личного участия дарителя непосредственное переоформление на одаряемого по сложившейся практике не проводится.')],['Даритель умер',deceased],['Даритель неизвестен / связи с ним нет',()=>five('При отсутствии связи с дарителем практический маршрут — регистрация фактического владельца на 5 лет.')]])}
function poa(){q('Может ли собственник, указанный в свидетельстве о регистрации транспортного средства ДНР, лично приехать в МРЭО?',[['Да',()=>q('Как будет оформлена передача транспортного средства?',[['Договор купли-продажи',sale],['Договор дарения',gift],['Другая ситуация / нет подходящего варианта',()=>other('Д-2Б.1.3')]])],['Нет, не может или не хочет приехать',()=>five('По сложившейся практике МРЭО доверенность сама по себе не используется для непосредственного переоформления транспортного средства с учёта ДНР без личного участия зарегистрированного собственника.')],['Собственник умер',deceased],['Собственник неизвестен / связи с ним нет',()=>five('При отсутствии зарегистрированного собственника практический маршрут — регистрация фактического владельца на 5 лет.')]])}
function courtFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ ПО РЕШЕНИЮ СУДА','<p><b>Право собственности подтверждено вступившим в законную силу решением суда РФ.</b></p><p>В этой ветке место проживания в ДНР не проверяется и личное участие прежнего собственника не требуется.</p><h3>📋 Что подготовить</h3><p>Паспорт РФ, вступившее в законную силу решение суда РФ, имеющиеся регистрационные документы и знаки ДНР, другие документы на транспортное средство; представить транспортное средство на осмотр. При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>🛑 Если отказали</h3><p>Получите письменное решение с конкретным правовым основанием; далее оцените административное или судебное обжалование.</p>')}
function court(){q('Имеется ли у вас решение суда Российской Федерации о признании за вами права собственности на транспортное средство?',[['Да, решение вступило в законную силу',()=>q('Являетесь ли вы гражданином Российской Федерации?',[['Да',courtFinal],['Нет',()=>pending('Требуется определить применимый порядок регистрации')]])],['Да, но решение ещё не вступило в законную силу',()=>pending('Необходимо дождаться вступления решения суда РФ в законную силу')]])}
function oral(){q('Может ли собственник, указанный в свидетельстве о регистрации транспортного средства ДНР, лично обратиться вместе с вами в МРЭО?',[['Да',()=>q('Как фактически транспортное средство было передано вам собственником?',[['Я купил транспортное средство',sale],['Транспортное средство было подарено мне',gift],['Другая ситуация / нет подходящего варианта',()=>other('Д-2Б.1.5.2')]])],['Нет, не может или не хочет приехать',()=>five('Письменная сделка отсутствует. Основание регистрации: объяснение владельца об обстоятельствах, при которых транспортное средство поступило в его владение. Указывайте только реальные обстоятельства.')],['Собственник умер',deceased],['Собственник неизвестен / связи с ним нет',()=>five('Основание регистрации: объяснение владельца об обстоятельствах, при которых транспортное средство поступило в его владение. Не оформляйте документы задним числом.')]])}
function lostAcq(){q('Может ли собственник, указанный в свидетельстве о регистрации транспортного средства ДНР, лично обратиться вместе с вами в МРЭО?',[['Да',()=>q('Как вы хотите оформить передачу транспортного средства от собственника?',[['Договор купли-продажи',sale],['Договор дарения',gift],['Другая ситуация / нет подходящего варианта',()=>other('Д-2Б.1.6.2')]])],['Нет, не может или не хочет приехать',()=>five('Документы о приобретении утрачены. Основание регистрации: объяснение владельца об обстоятельствах, при которых транспортное средство поступило в его владение. Не воссоздавайте документы задним числом.')],['Собственник умер',deceased],['Собственник неизвестен / связи с ним нет',()=>five('Документы о приобретении утрачены. Основание регистрации: объяснение владельца об обстоятельствах владения. Не воссоздавайте документы задним числом.')]])}
function diagnoseBasis(){q('Какие документы на транспортное средство у вас имеются?',[['Договор купли-продажи',sale],['Договор дарения',gift],['Доверенность',poa],['Решение суда РФ о признании права собственности',court],['Только свидетельство о регистрации транспортного средства ДНР',oral],['Другие документы',()=>other('Д-2Б.1.8')],['Документов о приобретении транспортного средства нет',oral]])}
function ownerBasis(){q('На каком основании транспортное средство находится у вас?',[['Договор купли-продажи',sale],['Договор дарения',gift],['Доверенность',poa],['Решение суда РФ о признании права собственности',court],['Сделка письменно не оформлялась — транспортное средство передано вместе со свидетельством о регистрации транспортного средства ДНР',oral],['Документы о приобретении утрачены',lostAcq],['Другое основание',()=>other('Д-2Б.1.7')]])}
function inheritanceOwnerFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ НА НАСЛЕДНИКА','<p><b>Основание:</b> свидетельство о праве на наследство на транспортное средство.</p><p>Место проживания наследника в ДНР на 30 сентября 2022 года в этой ветке не проверяется.</p><h3>📋 Что подготовить</h3><p>Паспорт РФ; свидетельство о праве на наследство; свидетельство о регистрации транспортного средства ДНР на имя умершего; государственные регистрационные знаки ДНР, если сохранились; иные имеющиеся документы; транспортное средство для осмотра.</p><p>При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>🛑 Если отказали</h3><p>Подайте документы официально и получите письменное решение с конкретным правовым основанием.</p>')}
function inheritanceOwner(){q('Являетесь ли вы гражданином Российской Федерации?',[['Да',inheritanceOwnerFinal],['Нет',()=>pending('Требуется определить применимый порядок регистрации')]])}
function heirBuyerProof(next){q('Имеются ли у вас документы, подтверждающие проживание на территории ДНР до вступления ДНР в состав Российской Федерации?',[['Да',next],['Нет',()=>pending('Требуется дополнительное подтверждение факта проживания')]])}
function heirBuyerResidence(next){q('Вы проживали на территории ДНР на момент принятия ДНР в состав Российской Федерации?',[['Да, проживал и сейчас проживаю в ДНР',()=>heirBuyerProof(next)],['Да, ранее проживал в ДНР, но сейчас проживаю или зарегистрирован в другом регионе РФ',()=>heirBuyerProof(next)],['Нет',()=>pending('Для этого маршрута требуется отдельная правовая оценка')]],accession)}
function heirBuyerCitizen(next){q('Являетесь ли вы как приобретатель гражданином Российской Федерации?',[['Да',()=>heirBuyerResidence(next)],['Нет',()=>pending('Требуется определить применимый порядок регистрации')]])}
function heirSaleFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ НА ПОКУПАТЕЛЯ','<p><b>Цепочка:</b> свидетельство о регистрации транспортного средства ДНР на умершего → свидетельство о праве на наследство → ДКП наследник–покупатель → регистрация РФ на покупателя.</p><p>Предварительно регистрировать транспортное средство на наследника не требуется. По принятой для Навигатора практике наследник лично участвует в оформлении в МРЭО.</p><p>При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>💰 Безопасная передача денег</h3><p>Окончательный расчёт целесообразно производить после совместного обращения в МРЭО и проверки возможности непосредственного оформления транспортного средства на покупателя.</p><h3>🛑 Если отказали</h3><p>Получите письменное решение с конкретным правовым основанием.</p>')}
function heirGiftFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ НА ОДАРЯЕМОГО','<p><b>Цепочка:</b> свидетельство о регистрации транспортного средства ДНР на умершего → свидетельство о праве на наследство → договор дарения наследник–одаряемый → регистрация РФ на одаряемого.</p><p>Предварительно регистрировать транспортное средство на наследника не требуется. По принятой для Навигатора практике наследник лично участвует в МРЭО.</p><p>При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>🛑 Если отказали</h3><p>Получите письменное решение с конкретным правовым основанием.</p>')}
function heirParticipation(next){q('Готов ли наследник, указанный в свидетельстве о праве на наследство, лично участвовать в оформлении транспортного средства в МРЭО?',[['Да, готов',()=>heirBuyerCitizen(next)],['Нет, не может или не хочет участвовать',()=>five('Наследник не участвует в оформлении. Практический маршрут фактического владельца — регистрация на 5 лет.')],['Наследник умер',()=>other('Новая наследственная цепочка')],['Связь с наследником утрачена',()=>five('Связь с наследником утрачена. Практический маршрут фактического владельца — регистрация на 5 лет.')]])}
function heirDisposition(){q('Как планируется оформить транспортное средство дальше?',[['Зарегистрировать транспортное средство на наследника',inheritanceOwner],['Продать транспортное средство нынешнему владельцу',()=>heirParticipation(heirSaleFinal)],['Подарить транспортное средство нынешнему владельцу',()=>heirParticipation(heirGiftFinal)],['Другая ситуация / нет подходящего варианта',()=>other('Д-2В.2.2')]])}
function inheritancePending(region='ДНР'){result('yellow','🟡 НАСЛЕДСТВО ЕЩЁ НЕ ОФОРМЛЕНО','<p>Свидетельство о праве на наследство на транспортное средство ещё не получено.</p><h3>⚖️ Возможны два маршрута</h3><p><b>1. Не ждать окончания оформления наследства.</b> Обратиться за регистрацией транспортного средства на российский учёт на ограниченный срок 5 лет. При успешной регистрации выдаётся <b>СТС РФ на ограниченный срок 5 лет без права продажи и с запретом на внесение изменений в регистрационные данные, а также государственные регистрационные номерные знаки РФ</b>. После получения свидетельства о праве на наследство можно обратиться в МРЭО для снятия ограничения и регистрации транспортного средства на постоянный российский учёт.</p><p><b>2. Дождаться свидетельства о праве на наследство.</b> После его получения обратиться непосредственно за постоянной регистрацией транспортного средства на российский учёт на основании наследства, без промежуточной регистрации на 5 лет.</p><h3>📋 Что выбрать</h3><p>Если транспортным средством необходимо пользоваться до завершения наследственного оформления, можно использовать первый маршрут. Если временная регистрация не требуется, можно дождаться свидетельства о праве на наследство и сразу перейти к постоянной регистрации.</p><h3>🛑 Если отказали</h3><p>Не ограничивайтесь устным отказом. Подайте документы официально и получите письменное решение МРЭО с конкретным правовым основанием.</p>')}
function inheritanceStatus(){q('Оформлено ли наследство на транспортное средство?',[['Да, имеется свидетельство о праве на наследство',heirDisposition],['Нет, наследство ещё не оформлено',()=>inheritancePending('ДНР')]])}
function heirs(){q('Известны ли вам наследники умершего собственника и готовы ли они участвовать в оформлении транспортного средства?',[['Да, наследники известны и готовы участвовать',inheritanceStatus],['Наследники известны, но не хотят участвовать',()=>five('Наличие наследников и их нежелание участвовать не создаёт у фактического владельца право собственности. Основание 5-летней регистрации — объяснение о реальных обстоятельствах владения.')],['Наследники неизвестны / связи с ними нет',()=>five('Разыскивать наследников как предварительное условие этого маршрута Навигатор не требует. Пятилетняя регистрация не создаёт право собственности.')],['Наследников нет',()=>five('Отсутствие наследников само по себе не делает фактического владельца собственником. Вопрос приобретения права собственности решается отдельно.')]])}
function deceased(){q('Имеется ли у вас документ, подтверждающий ваше право собственности на транспортное средство?',[['Свидетельство о праве на наследство, выданное на моё имя',inheritanceOwner],['Вступившее в законную силу решение суда РФ о признании за мной права собственности',court],['Нет, такого документа у меня нет',heirs],['Другой документ / другая ситуация',()=>other('Д-2В.1')]])}
function d2(){q('На кого оформлено свидетельство о регистрации транспортного средства ДНР?',[['На меня',citizen],['На другого человека',ownerBasis],['На умершего собственника',deceased],['Другая ситуация / нет подходящего варианта',()=>other('Д-2')]])}

function tempFiveOwner1(region){q('Когда транспортное средство впервые было поставлено на временный регистрационный учёт '+region+' на ваше имя?',[['Первая временная регистрация '+region+' была оформлена 5 лет назад или ранее',()=>tempFiveOwner1Result(region,true)],['С момента первой временной регистрации прошло менее 5 лет',()=>tempFiveOwner1Result(region,false)]],'<p>ℹ️ Если свидетельство о регистрации '+region+' выдавалось или заменялось неоднократно, ориентируйтесь на первую временную регистрацию транспортного средства на ваше имя.</p>')}
function tempFiveOwner1Result(region,fivePlus){result('yellow',fivePlus?'🟡 ДВА РАВНОЗНАЧНЫХ МАРШРУТА':'🟡 РЕГИСТРАЦИЯ РФ НА ОГРАНИЧЕННЫЙ СРОК — 5 ЛЕТ','<p>Вы являетесь <b>Владельцем 1</b>: указаны в свидетельстве о регистрации транспортного средства '+region+'.</p><h3>⚖️ Что предусматривает маршрут</h3><p>Транспортное средство может быть зарегистрировано на российский государственный учёт на ограниченный срок 5 лет. При успешной регистрации выдаются <b>СТС РФ на ограниченный срок 5 лет без права продажи и с запретом на внесение изменений в регистрационные данные, а также государственные регистрационные номерные знаки РФ</b>. Такая регистрация сама по себе не означает признания права собственности на транспортное средство.</p>'+(fivePlus?'<h3>⚖️ Второй равнозначный маршрут</h3><p>Поскольку с первой временной регистрации прошло 5 лет или более, можно отдельно рассмотреть обращение в суд о признании права собственности по приобретательной давности при наличии остальных предусмотренных законом условий. Истечение пяти лет само по себе право собственности не создаёт.</p><p><a href="https://rk-avtopravo.ru/pravo-sobstvennosti-na-avtomobil-v-novih-regionah/" target="_blank" rel="noopener">Подробнее о приобретательной давности транспортного средства</a>.</p>':'<p>Пятилетний срок владения в этой ветке ещё не достигнут, поэтому маршрут по приобретательной давности на основании пятилетнего срока пока не предлагается.</p>')+'<h3>📋 Что делать</h3><p>Представьте свидетельство о регистрации транспортного средства '+region+', имеющиеся документы и транспортное средство на осмотр.</p><h3>🛑 Если отказали</h3><p>Не ограничивайтесь устным отказом. Подайте документы официально и получите письменное решение с конкретным правовым основанием.</p>')}
function tempFiveOwner2(region,extra=''){result('yellow','🟡 РЕГИСТРАЦИЯ ТРАНСПОРТНОГО СРЕДСТВА НА ВЛАДЕЛЬЦА 2 НА РОССИЙСКИЙ УЧЁТ НА 5 ЛЕТ','<p>Во временном свидетельстве о регистрации '+region+' указан <b>Владелец 1</b>, а транспортным средством фактически владеете вы — <b>Владелец 2</b>.</p>'+extra+'<h3>⚖️ Что предусматривает маршрут</h3><p>По принятой в Навигаторе логике Владелец 2 может обратиться за временной регистрацией транспортного средства на российский государственный учёт на 5 лет на своё имя. При успешной регистрации выдаются <b>СТС РФ на ограниченный срок 5 лет без права продажи и с запретом на внесение изменений в регистрационные данные, а также государственные регистрационные номерные знаки РФ</b>. Такая регистрация сама по себе не означает признания права собственности.</p><h3>📋 Что делать</h3><p>Представьте имеющиеся регистрационные документы и транспортное средство на осмотр. Обстоятельства поступления транспортного средства во владение указывайте такими, какими они были в действительности.</p><p>ДКП, договор дарения, доверенность или расписка между Владельцем 1 и Владельцем 2 в этой ветке не рассматриваются как основание перехода права собственности.</p><h3>🚘 Как может быть на практике</h3><p>По известной нам практике МРЭО в подобных ситуациях нередко отказывает Владельцу 2 из-за того, что прежняя временная регистрация оформлена на другое лицо.</p><h3>📖 Подробнее</h3><p><a href="https://rk-avtopravo.ru/registraciya-avto-na-vladelca-2-sts-dnr-lnr/" target="_blank" rel="noopener">Регистрация транспортного средства на Владельца 2 со свидетельством ДНР/ЛНР</a></p><h3>🛑 Если отказали</h3><p>Не ограничивайтесь устным отказом. Получите письменное решение с конкретным правовым основанием и после этого оцените административное обжалование или обращение в суд.</p><h3>⚠️ Приобретательная давность</h3><p>Навигатор пока не присоединяет автоматически период владения Владельца 1 к периоду Владельца 2. Этот вопрос требует отдельной правовой оценки.</p>')}
function tempDeadOwner2(region){q('Временная регистрация '+region+' была оформлена на Владельца 1, который умер. Транспортное средство сейчас фактически находится у вас?',[['Да, транспортное средство фактически находится у меня — я Владелец 2',()=>tempFiveOwner2(region,'<p><b>Дополнительное обстоятельство:</b> Владелец 1 умер. Смерть Владельца 1 сама по себе не используется Навигатором как автоматический запрет пятилетнего маршрута.</p>')],['Другая ситуация / нет подходящего варианта',()=>other(region+'-ВР: умер Владелец 1')]],'<p>ℹ️ В этой ветке не рассматриваем наследование транспортного средства. Определяем маршрут фактического Владельца 2.</p>')}
function tempBranch(region){q('На кого оформлено свидетельство о временной регистрации транспортного средства '+region+'?',[['На меня — я Владелец 1',()=>tempFiveOwner1(region)],['На другого человека — я Владелец 2',()=>tempFiveOwner2(region)],['Владелец 1 умер',()=>tempDeadOwner2(region)],['Другая ситуация / нет подходящего варианта',()=>other(region+'-ВР.1')]],'<p>ℹ️ Для временной регистрации различаем Владельца 1 — лицо, указанное во свидетельстве '+region+', и Владельца 2 — фактического владельца, который в этом свидетельстве не указан.</p>')}
function tempDnr(){tempBranch('ДНР')}
function tempLnr(){tempBranch('ЛНР')}

function d1(){q('Какая регистрация указана в документах ДНР?',[['Постоянная регистрация',d2],['Регистрация на ограниченный срок — 5 лет',tempDnr],['Другая ситуация / нет подходящего варианта',()=>other('Д-1')]])}
function lnrP_mainResult(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ','<p><b>Транспортное средство соответствует условиям специального порядка регистрации на российский государственный учёт.</b></p><h3>⚖️ Что предусматривает закон</h3><p>По выбранным ответам препятствий для применения этого маршрута не выявлено.</p><h3>📋 Что делать</h3><p>Подготовить документы, подтверждающие личность, регистрацию транспортного средства ЛНР и постоянное либо прежнее постоянное проживание в ЛНР; представить транспортное средство на осмотр.</p><p>При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>🚘 Как может быть на практике</h3><p>При утрате документов, расхождениях сведений, проблемах с идентификаторами или ограничениях МРЭО может провести дополнительную проверку. Дополнительная проверка сама по себе не является отказом.</p><h3>🛑 Если отказали</h3><p>Не ограничивайтесь устным отказом. Просите принять документы и выдать письменное решение с указанием правового основания.</p>')}
function lnrP_proof(){q('Имеются ли у вас документы, подтверждающие постоянное проживание на территории ЛНР?',[['Да',lnrP_mainResult],['Нет',()=>pending('Нет документов о постоянном проживании')]])}
function lnrP_residence(){q('Вы проживали или были зарегистрированы по месту жительства на территории ЛНР на момент принятия ЛНР в состав Российской Федерации?',[['Да, проживал в ЛНР',lnrP_proof],['Да, был зарегистрирован по месту жительства в ЛНР',lnrP_proof],['Да, проживал в ЛНР и был зарегистрирован по месту жительства',lnrP_proof],['Нет, не проживал и не был зарегистрирован по месту жительства в ЛНР',()=>result('red','🔴 СПЕЦИАЛЬНЫЙ ПОРЯДОК НЕ ПРИМЕНЯЕТСЯ','<p>По выбранным ответам территориальное условие для этого маршрута не выполнено.</p><h3>🛑 Если считаете вывод неверным</h3><p>Проверьте документы и измените ответы. Если МРЭО отказало в конкретной ситуации, получите письменное решение с указанием правового основания.</p>')]],accession)}
function lnrP_citizen(){q('Являетесь ли вы гражданином Российской Федерации?',[['Да',lnrP_residence],['Нет',()=>pending('Нет гражданства РФ')]])}
function lnrP_buyerProof(next){q('Имеются ли у вас документы, подтверждающие проживание или регистрацию по месту жительства на территории ЛНР?',[['Да',next],['Нет',()=>pending('Требуется дополнительное подтверждение проживания или регистрации по месту жительства в ЛНР')]])}
function lnrP_buyerResidence(next=lnrP_mainResult){q('Вы проживали или были зарегистрированы по месту жительства на территории ЛНР на момент принятия ЛНР в состав Российской Федерации?',[['Да, проживал в ЛНР',()=>lnrP_buyerProof(next)],['Да, был зарегистрирован по месту жительства в ЛНР',()=>lnrP_buyerProof(next)],['Да, проживал в ЛНР и был зарегистрирован по месту жительства',()=>lnrP_buyerProof(next)],['Нет, не проживал и не был зарегистрирован по месту жительства в ЛНР',()=>result('red','🔴 РЕГИСТРАЦИЯ НА ПРИОБРЕТАТЕЛЯ ПО ЭТОМУ МАРШРУТУ НЕ ПРЕДУСМОТРЕНА','<p>По выбранным ответам приобретатель не проживал и не был зарегистрирован по месту жительства в ЛНР на момент принятия ЛНР в состав Российской Федерации.</p><p>Пятилетняя регистрация не предлагается как автоматическая замена этому условию.</p><h3>🛑 Если отказали</h3><p>Получите письменное решение МРЭО и проверьте его правовое основание.</p>')]],accession)}
function lnrP_buyerCitizen(next=lnrP_mainResult){q('Являетесь ли вы гражданином Российской Федерации?',[['Да',()=>lnrP_buyerResidence(next)],['Нет',()=>pending('Требуется определить применимый порядок регистрации')]])}
function lnrP_saleFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ НА ПОКУПАТЕЛЯ','<p><b>Транспортное средство может быть оформлено непосредственно на покупателя.</b></p><h3>🚘 Как может быть на практике</h3><p>Для непосредственного переоформления требуется личное участие собственника, указанного в свидетельстве о регистрации транспортного средства ЛНР.</p><h3>📋 Что делать</h3><p>Подготовить ДКП в 3 экземплярах, документы сторон и транспортного средства, документы о проживании покупателя; представить транспортное средство на осмотр. При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>💰 Как безопаснее передать деньги</h3><p>Не рекомендуется полный расчёт до проверки возможности оформления: ДКП → совместное обращение в МРЭО → проверка и принятие документов → окончательный расчёт. Аванс фиксируйте письменно; наличные — распиской; перевод — с понятным назначением платежа.</p><h3>🛑 Если отказали</h3><p>Получите письменное решение с конкретным правовым основанием.</p>')}
function lnrP_sale(){q('Может ли собственник, указанный в свидетельстве о регистрации транспортного средства ЛНР, лично обратиться вместе с вами в МРЭО?',[['Да, может лично приехать в МРЭО',()=>q('Является ли собственник, указанный в свидетельстве о регистрации транспортного средства ЛНР, гражданином Российской Федерации?',[['Да',()=>lnrP_buyerCitizen(lnrP_saleFinal)],['Нет',()=>pending('Требуется определить применимый порядок регистрации')]])],['Нет, не может или не хочет приехать',()=>lnrP_five('Без личного участия собственника непосредственное переоформление на покупателя по сложившейся практике не проводится.')],['Собственник умер',lnrP_deceased],['Собственник неизвестен / связи с ним нет',()=>lnrP_five('При отсутствии связи с собственником практический маршрут — специальная регистрация фактического владельца на 5 лет.')]])}
function lnrP_giftFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ НА ОДАРЯЕМОГО','<p><b>Основание перехода права собственности — договор дарения.</b></p><h3>🚘 Как может быть на практике</h3><p>Для непосредственного переоформления требуется личное участие дарителя, указанного собственником в свидетельстве о регистрации транспортного средства ЛНР.</p><h3>📋 Что делать</h3><p>Оформить договор дарения, подготовить документы сторон и транспортного средства, документы о проживании одаряемого и представить транспортное средство на осмотр. При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>🛑 Если отказали</h3><p>Получите письменное решение с конкретным правовым основанием.</p>')}
function lnrP_gift(){q('Может ли даритель, указанный собственником в свидетельстве о регистрации транспортного средства ЛНР, лично обратиться вместе с вами в МРЭО?',[['Да, может лично приехать в МРЭО',()=>q('Является ли даритель, указанный собственником в свидетельстве о регистрации транспортного средства ЛНР, гражданином Российской Федерации?',[['Да',()=>lnrP_buyerCitizen(lnrP_giftFinal)],['Нет',()=>pending('Требуется определить применимый порядок регистрации')]])],['Нет, не может или не хочет приехать',()=>lnrP_five('Без личного участия дарителя непосредственное переоформление на одаряемого по сложившейся практике не проводится.')],['Даритель умер',lnrP_deceased],['Даритель неизвестен / связи с ним нет',()=>lnrP_five('При отсутствии связи с дарителем практический маршрут — регистрация фактического владельца на 5 лет.')]])}
function lnrP_poa(){q('Может ли собственник, указанный в свидетельстве о регистрации транспортного средства ЛНР, лично приехать в МРЭО?',[['Да',()=>q('Как будет оформлена передача транспортного средства?',[['Договор купли-продажи',lnrP_sale],['Договор дарения',lnrP_gift],['Другая ситуация / нет подходящего варианта',()=>other('Л-2Б.1.3')]])],['Нет, не может или не хочет приехать',()=>lnrP_five('По сложившейся практике МРЭО доверенность сама по себе не используется для непосредственного переоформления транспортного средства с учёта ЛНР без личного участия зарегистрированного собственника.')],['Собственник умер',lnrP_deceased],['Собственник неизвестен / связи с ним нет',()=>lnrP_five('При отсутствии зарегистрированного собственника практический маршрут — регистрация фактического владельца на 5 лет.')]])}
function lnrP_courtFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ ПО РЕШЕНИЮ СУДА','<p><b>Право собственности подтверждено вступившим в законную силу решением суда РФ.</b></p><p>В этой ветке место проживания в ЛНР не проверяется и личное участие прежнего собственника не требуется.</p><h3>📋 Что подготовить</h3><p>Паспорт РФ, вступившее в законную силу решение суда РФ, имеющиеся регистрационные документы и знаки ЛНР, другие документы на транспортное средство; представить транспортное средство на осмотр. При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>🛑 Если отказали</h3><p>Получите письменное решение с конкретным правовым основанием; далее оцените административное или судебное обжалование.</p>')}
function lnrP_court(){q('Имеется ли у вас решение суда Российской Федерации о признании за вами права собственности на транспортное средство?',[['Да, решение вступило в законную силу',()=>q('Являетесь ли вы гражданином Российской Федерации?',[['Да',lnrP_courtFinal],['Нет',()=>pending('Требуется определить применимый порядок регистрации')]])],['Да, но решение ещё не вступило в законную силу',()=>pending('Необходимо дождаться вступления решения суда РФ в законную силу')]])}
function lnrP_oral(){q('Может ли собственник, указанный в свидетельстве о регистрации транспортного средства ЛНР, лично обратиться вместе с вами в МРЭО?',[['Да',()=>q('Как фактически транспортное средство было передано вам собственником?',[['Я купил транспортное средство',lnrP_sale],['Транспортное средство было подарено мне',lnrP_gift],['Другая ситуация / нет подходящего варианта',()=>other('Л-2Б.1.5.2')]])],['Нет, не может или не хочет приехать',()=>lnrP_five('Письменная сделка отсутствует. Основание регистрации: объяснение владельца об обстоятельствах, при которых транспортное средство поступило в его владение. Указывайте только реальные обстоятельства.')],['Собственник умер',lnrP_deceased],['Собственник неизвестен / связи с ним нет',()=>lnrP_five('Основание регистрации: объяснение владельца об обстоятельствах, при которых транспортное средство поступило в его владение. Не оформляйте документы задним числом.')]])}
function lnrP_lostAcq(){q('Может ли собственник, указанный в свидетельстве о регистрации транспортного средства ЛНР, лично обратиться вместе с вами в МРЭО?',[['Да',()=>q('Как вы хотите оформить передачу транспортного средства от собственника?',[['Договор купли-продажи',lnrP_sale],['Договор дарения',lnrP_gift],['Другая ситуация / нет подходящего варианта',()=>other('Л-2Б.1.6.2')]])],['Нет, не может или не хочет приехать',()=>lnrP_five('Документы о приобретении утрачены. Основание регистрации: объяснение владельца об обстоятельствах, при которых транспортное средство поступило в его владение. Не воссоздавайте документы задним числом.')],['Собственник умер',lnrP_deceased],['Собственник неизвестен / связи с ним нет',()=>lnrP_five('Документы о приобретении утрачены. Основание регистрации: объяснение владельца об обстоятельствах владения. Не воссоздавайте документы задним числом.')]])}
function lnrP_diagnoseBasis(){q('Какие документы на транспортное средство у вас имеются?',[['Договор купли-продажи',lnrP_sale],['Договор дарения',lnrP_gift],['Доверенность',lnrP_poa],['Решение суда РФ о признании права собственности',lnrP_court],['Только свидетельство о регистрации транспортного средства ЛНР',lnrP_oral],['Другие документы',()=>other('Л-2Б.1.8')],['Документов о приобретении транспортного средства нет',lnrP_oral]])}
function lnrP_ownerBasis(){q('На каком основании транспортное средство находится у вас?',[['Договор купли-продажи',lnrP_sale],['Договор дарения',lnrP_gift],['Доверенность',lnrP_poa],['Решение суда РФ о признании права собственности',lnrP_court],['Сделка письменно не оформлялась — транспортное средство передано вместе со свидетельством о регистрации транспортного средства ЛНР',lnrP_oral],['Документы о приобретении утрачены',lnrP_lostAcq],['Другое основание',()=>other('Л-2Б.1.7')]])}
function lnrP_inheritanceOwnerFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ НА НАСЛЕДНИКА','<p><b>Основание:</b> свидетельство о праве на наследство на транспортное средство.</p><p>Место проживания наследника в ЛНР на 30 сентября 2022 года в этой ветке не проверяется.</p><h3>📋 Что подготовить</h3><p>Паспорт РФ; свидетельство о праве на наследство; свидетельство о регистрации транспортного средства ЛНР на имя умершего; государственные регистрационные знаки ЛНР, если сохранились; иные имеющиеся документы; транспортное средство для осмотра.</p><p>При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>🛑 Если отказали</h3><p>Подайте документы официально и получите письменное решение с конкретным правовым основанием.</p>')}
function lnrP_inheritanceOwner(){q('Являетесь ли вы гражданином Российской Федерации?',[['Да',lnrP_inheritanceOwnerFinal],['Нет',()=>pending('Требуется определить применимый порядок регистрации')]])}
