function lnrP_heirSaleFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ НА ПОКУПАТЕЛЯ','<p><b>Цепочка:</b> свидетельство о регистрации транспортного средства ЛНР на умершего → свидетельство о праве на наследство → ДКП наследник–покупатель → регистрация РФ на покупателя.</p><p>Предварительно регистрировать транспортное средство на наследника не требуется. По принятой для Навигатора практике наследник лично участвует в оформлении в МРЭО.</p><p>При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>💰 Безопасная передача денег</h3><p>Окончательный расчёт целесообразно производить после совместного обращения в МРЭО и проверки возможности непосредственного оформления транспортного средства на покупателя.</p><h3>🛑 Если отказали</h3><p>Получите письменное решение с конкретным правовым основанием.</p>')}
function lnrP_heirGiftFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ НА ОДАРЯЕМОГО','<p><b>Цепочка:</b> свидетельство о регистрации транспортного средства ЛНР на умершего → свидетельство о праве на наследство → договор дарения наследник–одаряемый → регистрация РФ на одаряемого.</p><p>Предварительно регистрировать транспортное средство на наследника не требуется. По принятой для Навигатора практике наследник лично участвует в МРЭО.</p><p>При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>🛑 Если отказали</h3><p>Получите письменное решение с конкретным правовым основанием.</p>')}
function lnrP_heirParticipation(next){q('Готов ли наследник, указанный в свидетельстве о праве на наследство, лично участвовать в оформлении транспортного средства в МРЭО?',[['Да, готов',()=>lnrP_heirBuyerCitizen(next)],['Нет, не может или не хочет участвовать',()=>lnrP_five('Наследник не участвует в оформлении. Практический маршрут фактического владельца — регистрация на 5 лет.')],['Наследник умер',()=>other('Новая наследственная цепочка')],['Связь с наследником утрачена',()=>lnrP_five('Связь с наследником утрачена. Практический маршрут фактического владельца — регистрация на 5 лет.')]])}
function lnrP_heirDisposition(){q('Как планируется оформить транспортное средство дальше?',[['Зарегистрировать транспортное средство на наследника',lnrP_inheritanceOwner],['Продать транспортное средство нынешнему владельцу',()=>lnrP_heirParticipation(lnrP_heirSaleFinal)],['Подарить транспортное средство нынешнему владельцу',()=>lnrP_heirParticipation(lnrP_heirGiftFinal)],['Другая ситуация / нет подходящего варианта',()=>other('Л-2В.2.2')]])}
function lnrP_inheritancePending(){result('yellow','🟡 НАСЛЕДСТВО ЕЩЁ НЕ ОФОРМЛЕНО','<p>Свидетельство о праве на наследство на транспортное средство ещё не получено.</p><h3>⚖️ Возможны два маршрута</h3><p><b>1. Не ждать окончания оформления наследства.</b> Обратиться за регистрацией транспортного средства на российский учёт на ограниченный срок 5 лет. При успешной регистрации выдаётся <b>СТС РФ на ограниченный срок 5 лет без права продажи и с запретом на внесение изменений в регистрационные данные, а также государственные регистрационные номерные знаки РФ</b>. После получения свидетельства о праве на наследство можно обратиться в МРЭО для снятия ограничения и регистрации транспортного средства на постоянный российский учёт.</p><p><b>2. Дождаться свидетельства о праве на наследство.</b> После его получения обратиться непосредственно за постоянной регистрацией транспортного средства на российский учёт на основании наследства, без промежуточной регистрации на 5 лет.</p><h3>📋 Что выбрать</h3><p>Если транспортным средством необходимо пользоваться до завершения наследственного оформления, можно использовать первый маршрут. Если временная регистрация не требуется, можно дождаться свидетельства о праве на наследство и сразу перейти к постоянной регистрации.</p><h3>🛑 Если отказали</h3><p>Не ограничивайтесь устным отказом. Подайте документы официально и получите письменное решение МРЭО с конкретным правовым основанием.</p>')}
function lnrP_inheritanceStatus(){q('Оформлено ли наследство на транспортное средство?',[['Да, имеется свидетельство о праве на наследство',lnrP_heirDisposition],['Нет, наследство ещё не оформлено',lnrP_inheritancePending]])}
function lnrP_heirs(){q('Известны ли вам наследники умершего собственника и готовы ли они участвовать в оформлении транспортного средства?',[['Да, наследники известны и готовы участвовать',lnrP_inheritanceStatus],['Наследники известны, но не хотят участвовать',()=>lnrP_five('Наличие наследников и их нежелание участвовать не создаёт у фактического владельца право собственности. Основание 5-летней регистрации — объяснение о реальных обстоятельствах владения.')],['Наследники неизвестны / связи с ними нет',()=>lnrP_five('Разыскивать наследников как предварительное условие этого маршрута Навигатор не требует. Пятилетняя регистрация не создаёт право собственности.')],['Наследников нет',()=>lnrP_five('Отсутствие наследников само по себе не делает фактического владельца собственником. Вопрос приобретения права собственности решается отдельно.')]])}
function lnrP_deceased(){q('Имеется ли у вас документ, подтверждающий ваше право собственности на транспортное средство?',[['Свидетельство о праве на наследство, выданное на моё имя',lnrP_inheritanceOwner],['Вступившее в законную силу решение суда РФ о признании за мной права собственности',lnrP_court],['Нет, такого документа у меня нет',lnrP_heirs],['Другой документ / другая ситуация',()=>other('Л-2В.1')]])}
function lnrP_five(reason){result('yellow','🟡 Регистрация на 5 лет','<p><b>Статус:</b> владение транспортным средством (не являюсь собственником по свидетельству о регистрации транспортного средства ЛНР).</p><p><b>Основание регистрации при отсутствии иного документа:</b> объяснение владельца об обстоятельствах владения транспортным средством. Указывать необходимо реальные обстоятельства получения и пользования транспортным средством.</p><p>'+reason+'</p><p><b>Практика:</b> если МРЭО становится известно о смерти собственника по свидетельству о регистрации транспортного средства ЛНР, возможен фактический отказ. В таком случае следует получить письменное решение с конкретным правовым основанием.</p><p class="warn"><b>⚠️ Нельзя оформлять ДКП задним числом от имени умершего, подделывать его подпись или использовать заведомо подложные документы.</b> Это может повлечь спор с наследниками, отказ в регистрации, а в зависимости от обстоятельств — уголовную ответственность.</p><p>Если наследники найдутся и готовы участвовать, возможен законный маршрут: оформление наследства → новая сделка с наследником → регистрация приобретателя при соблюдении условий специального порядка.</p>')}
function lnrOwnerFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ','<p><b>⚖️ Что предусматривает закон</b></p><p>При выполнении условий этой ветки транспортное средство подпадает под специальный порядок перерегистрации на российский государственный учёт. Регистрация производится постоянно, а не на 5 лет.</p><p><b>🚘 Что получает владелец</b></p><p><b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ.</b></p><p><b>📋 Что делать</b></p><p>Обратиться в МРЭО с транспортным средством и документами: паспортом РФ, свидетельством о регистрации транспортного средства ЛНР, имеющимися документами на транспортное средство, регистрационными знаками ЛНР и документами, подтверждающими проживание на территории ЛНР до вступления ЛНР в состав Российской Федерации.</p><p><b>🛑 Если МРЭО отказывает</b></p><p>Не ограничивайтесь устным отказом. Представьте документы официально и получите письменное решение с указанием конкретного правового основания отказа. После этого можно определить дальнейший способ защиты.</p><p><b>📚 Нормативные основания</b></p><p>Точные реквизиты и пункты будут внесены после проверки окончательной редакции нового постановления Правительства РФ.</p>')}
function lnrProof(){q('Имеются ли у вас документы, подтверждающие проживание или регистрацию по месту жительства на территории ЛНР?',[['Да',lnrOwnerFinal],['Нет',()=>pending('Необходимо дополнительно подтвердить проживание или регистрацию по месту жительства на территории ЛНР')]])}
function lnrResidence(){q('Вы проживали или были зарегистрированы по месту жительства на территории ЛНР на момент принятия ЛНР в состав Российской Федерации?',[['Да, проживал в ЛНР',lnrProof],['Да, был зарегистрирован по месту жительства в ЛНР',lnrProof],['Да, проживал в ЛНР и был зарегистрирован по месту жительства',lnrProof],['Нет, не проживал и не был зарегистрирован по месту жительства в ЛНР',()=>result('red','🔴 СПЕЦИАЛЬНЫЙ ПОРЯДОК НЕ ПРИМЕНЯЕТСЯ','<p>По выбранным ответам территориальное условие для этого маршрута не выполнено.</p><h3>🛑 Если считаете вывод неверным</h3><p>Проверьте документы и измените ответы. При фактическом отказе МРЭО получите письменное решение с указанием правового основания.</p>')]],'<p>ℹ️ ЛНР принята в состав Российской Федерации <b>30 сентября 2022 года</b>.</p>')}
function lnrCitizen(){q('Являетесь ли вы гражданином Российской Федерации?',[['Да',lnrResidence],['Нет',()=>pending('Требуется определить применимый порядок регистрации')]])}
function lnrOwner(){q('На кого оформлено свидетельство о регистрации транспортного средства ЛНР?',[['На меня',lnrP_citizen],['На другого человека',lnrP_ownerBasis],['На умершего собственника',lnrP_deceased],['Другая ситуация / нет подходящего варианта',()=>other('Л-2')]])}

function limpArticle(){return '<p><b>📖 Подробнее:</b> <a href="https://rk-avtopravo.ru/kak-podtverdit-registraciyu-avtomobilya-lnr/" target="_blank" rel="noopener">Как подтвердить прежнюю регистрацию транспортного средства в ЛНР</a>.</p>'}
function limpMainArticle(){return '<p><b>📖 Подробнее:</b> <a href="https://rk-avtopravo.ru/avto-iz-za-rubezha-v-lnr-registraciya-rf/" target="_blank" rel="noopener">Транспортные средства, ввезённые из-за рубежа в ЛНР: регистрация на российский учёт</a>.</p>'}
function limpOwnerFivePlus(){result('yellow','🟡 ДВА РАВНОЗНАЧНЫХ МАРШРУТА','<p>Вы являетесь <b>Владельцем 1</b>, а с момента первой временной регистрации транспортного средства в ЛНР на ваше имя прошло 5 лет или более.</p><h3>1. Регистрация на российский учёт на 5 лет</h3><p>Можно использовать маршрут временной регистрации транспортного средства на российский государственный учёт на 5 лет. При успешной регистрации выдаются <b>СТС РФ на ограниченный срок 5 лет без права продажи и с запретом на внесение изменений в регистрационные данные, а также государственные регистрационные номерные знаки РФ</b>. Такая регистрация сама по себе не означает признания права собственности на транспортное средство.</p><h3>2. Приобретательная давность</h3><p>Можно отдельно рассмотреть обращение в суд с требованием о признании права собственности по приобретательной давности. Для оценки пятилетнего периода в этой ветке учитывается срок с <b>первой временной регистрации транспортного средства в ЛНР на ваше имя</b>, а не только дата последнего свидетельства.</p><p><b>Важно:</b> истечение пяти лет само по себе не означает автоматического возникновения права собственности. Для судебного маршрута необходимо оценить и остальные предусмотренные законом условия приобретательной давности.</p><h3>📋 Если история регистрации подтверждена не полностью</h3><p>Запросите в МРЭО сведения обо всей последовательности временных регистраций. Если получить необходимые сведения самостоятельно не удаётся и дело уже рассматривается судом, можно просить суд истребовать их.</p>'+limpMainArticle()+'<p><b>📖 Приобретательная давность:</b> <a href="https://rk-avtopravo.ru/pravo-sobstvennosti-na-avtomobil-v-novih-regionah/" target="_blank" rel="noopener">Право собственности на транспортное средство в новых регионах</a>.</p><h3>🛑 Если МРЭО отказало в регистрации на 5 лет</h3><p>Не ограничивайтесь устным отказом. Подайте документы официально и получите письменное решение с конкретным правовым основанием. После этого можно оценивать административное обжалование и обращение в суд.</p>')}
function limpOwnerUnderFive(){result('yellow','🟡 РЕГИСТРАЦИЯ РФ НА 5 ЛЕТ','<p>Вы являетесь <b>Владельцем 1</b>, но с момента первой временной регистрации транспортного средства в ЛНР на ваше имя ещё не прошло 5 лет.</p><h3>⚖️ Что предусматривает маршрут</h3><p>На данном этапе Навигатор предлагает маршрут временной регистрации транспортного средства на российский государственный учёт на 5 лет. При успешной регистрации выдаются <b>СТС РФ на ограниченный срок 5 лет без права продажи и с запретом на внесение изменений в регистрационные данные, а также государственные регистрационные номерные знаки РФ</b>. Такая регистрация сама по себе не означает признания права собственности.</p><p>Судебный маршрут по приобретательной давности на основании пятилетнего срока в этой ветке пока не предлагается.</p>'+limpMainArticle()+'<h3>🛑 Если отказали</h3><p>Не ограничивайтесь устным отказом. Подайте документы официально и получите письменное решение с конкретным правовым основанием. После этого можно оценивать административное обжалование и обращение в суд.</p>')}
function limpFirstDate(){q('Когда транспортное средство впервые было поставлено на временный регистрационный учёт ЛНР на ваше имя?',[['Первая временная регистрация ЛНР была оформлена 5 лет назад или ранее',limpOwnerFivePlus],['С момента первой временной регистрации прошло менее 5 лет',limpOwnerUnderFive]],'<p>ℹ️ Если свидетельство временной регистрации ЛНР выдавалось неоднократно, ориентируйтесь на <b>первую временную регистрацию транспортного средства на ваше имя</b>, а не на дату последнего выданного свидетельства.</p>')}
function limpDeadOwner2Final(extra=''){result('yellow','🟡 РЕГИСТРАЦИЯ НА ВЛАДЕЛЬЦА 2 НА РОССИЙСКИЙ УЧЁТ НА 5 ЛЕТ','<p>Временная регистрация ЛНР была оформлена на <b>Владельца 1, который умер</b>, а транспортное средство фактически находится у вас — <b>Владельца 2</b>.</p>'+extra+'<h3>⚖️ Что предусматривает маршрут</h3><p>По принятой в Навигаторе логике смерть Владельца 1 сама по себе не исключает обращение Владельца 2 за временной регистрацией транспортного средства на российский государственный учёт на 5 лет. При успешной регистрации выдаются <b>СТС РФ на ограниченный срок 5 лет без права продажи и с запретом на внесение изменений в регистрационные данные, а также государственные регистрационные номерные знаки РФ</b>. Такая регистрация сама по себе не означает признания права собственности.</p><h3>📋 Что делать</h3><p>Подайте документы в МРЭО официально, представьте имеющиеся документы на транспортное средство и транспортное средство на осмотр. Обстоятельства поступления транспортного средства во владение указывайте такими, какими они были в действительности.</p><p>Если документы временной регистрации ЛНР, оформленные на умершего Владельца 1, отсутствуют, Навигатор не предлагает Владельцу 2 восстанавливать их от имени умершего. Используются имеющиеся документы и иные допустимые сведения об истории транспортного средства.</p><h3>🚘 Как может быть на практике</h3><p>В этой ситуации возможен отказ МРЭО, особенно если временная регистрация оформлялась на умершего Владельца 1 и подтверждающих документов недостаточно. Практический отказ не приравниваем к автоматическому отсутствию пятилетнего маршрута.</p><h3>📖 Подробнее</h3><p><a href="https://rk-avtopravo.ru/registraciya-avto-na-vladelca-2-sts-dnr-lnr/" target="_blank" rel="noopener">Регистрация транспортного средства на Владельца 2 со свидетельством ДНР/ЛНР</a></p>'+limpMainArticle()+'<h3>🛑 Если отказали</h3><p>Не ограничивайтесь устным отказом. Потребуйте принять документы и выдать письменное решение с конкретным правовым основанием. После получения решения необходимо отдельно оценить основания для административного обжалования или обращения в суд.</p><h3>⚠️ Приобретательная давность</h3><p>Навигатор не делает автоматический вывод о присоединении периода владения умершего Владельца 1 к периоду Владельца 2. Этот вопрос оставлен для отдельной правовой оценки.</p>')}
function limpDeadOwnerDocs(){q('Сохранились ли документы временной регистрации ЛНР, оформленные на умершего Владельца 1?',[['Да, документы сохранились',()=>limpDeadOwner2Final('<p><b>Документы:</b> сохранились документы временной регистрации ЛНР, оформленные на умершего Владельца 1.</p>')],['Нет, документы были изъяты в МРЭО или утрачены',limpDeadOwnerUkraineDocs],['Другая ситуация / нет подходящего варианта',()=>other('Л-ИМП.2В.2')]],'<p>ℹ️ Если документы временной регистрации умершего Владельца 1 отсутствуют, Владелец 2 не направляется Навигатором на восстановление этих документов от своего имени. Далее проверяем дополнительные документы, которыми можно подтвердить историю транспортного средства.</p>')}
function limpDeadOwnerUkraineDocs(){q('Сохранились ли украинские регистрационные документы на транспортное средство?',[['Да, сохранились',()=>limpDeadOwner2Final('<p><b>Документы:</b> документы временной регистрации ЛНР отсутствуют, но сохранились украинские регистрационные документы. Они могут дополнительно подтверждать историю транспортного средства.</p>')],['Нет, украинских регистрационных документов нет',()=>limpDeadOwner2Final('<p><b>Документы:</b> документы временной регистрации ЛНР и украинские регистрационные документы отсутствуют. Это не используется Навигатором как автоматический запрет пятилетнего маршрута, но существенно повышает доказательственную сложность.</p>')],['Другая ситуация / нет подходящего варианта',()=>other('Л-ИМП.2В.3')]],'<p>ℹ️ Наличие украинских регистрационных документов может упростить подтверждение истории транспортного средства. Их отсутствие само по себе не используется как автоматический запрет пятилетней регистрации.</p>')}
function limpDeadHolder(){q('Временная регистрация ЛНР была оформлена на Владельца 1, который умер. Транспортное средство сейчас фактически находится у вас?',[['Да, транспортное средство фактически находится у меня — я Владелец 2',limpDeadOwnerDocs],['Другая ситуация / нет подходящего варианта',()=>other('Л-ИМП.2В.1')]],'<p>ℹ️ В этой ветке не рассматриваем наследование транспортного средства. Навигатор определяет дальнейший маршрут для фактического Владельца 2 после смерти лица, на которое была оформлена временная регистрация ЛНР.</p>')}
function limpOwner2Final(extra=''){result('yellow','🟡 РЕГИСТРАЦИЯ ТРАНСПОРТНОГО СРЕДСТВА НА ВЛАДЕЛЬЦА 2 НА РОССИЙСКИЙ УЧЁТ НА 5 ЛЕТ','<p>Во временном свидетельстве о регистрации ЛНР указан <b>Владелец 1</b>, а транспортным средством фактически владеете вы — <b>Владелец 2</b>.</p>'+extra+'<h3>⚖️ Что предусматривает маршрут</h3><p>По принятой в Навигаторе логике Владелец 2 может обратиться за временной регистрацией транспортного средства на российский государственный учёт на 5 лет на своё имя. При успешной регистрации выдаются <b>СТС РФ на ограниченный срок 5 лет без права продажи и с запретом на внесение изменений в регистрационные данные, а также государственные регистрационные номерные знаки РФ</b>. Такая регистрация сама по себе не означает признания права собственности на транспортное средство.</p><h3>📋 Что делать</h3><p>Подготовьте сохранившееся свидетельство временной регистрации ЛНР либо официальное подтверждение прежней временной регистрации, имеющиеся регистрационные документы на транспортное средство и представьте транспортное средство на осмотр. Обстоятельства фактического владения указывайте такими, какими они были в действительности.</p><p>ДКП, договор дарения, доверенность или расписка между Владельцем 1 и Владельцем 2 в этой ветке не рассматриваются как основание перехода права собственности на транспортное средство.</p><h3>🚘 Как может быть на практике</h3><p>По известной нам практике МРЭО в подобных ситуациях нередко отказывает Владельцу 2 из-за того, что прежняя временная регистрация оформлена на другое лицо. Практический отказ не приравниваем к отсутствию самого маршрута: документы следует подать официально и потребовать письменное решение.</p><h3>📖 Подробнее о регистрации на Владельца 2</h3><p><a href="https://rk-avtopravo.ru/registraciya-avto-na-vladelca-2-sts-dnr-lnr/" target="_blank" rel="noopener">Регистрация транспортного средства на Владельца 2 со свидетельством ДНР/ЛНР</a></p>'+limpMainArticle()+'<h3>🛑 Если отказали</h3><p>Не ограничивайтесь устным отказом. Получите письменное решение МРЭО с конкретным правовым основанием, проанализируйте его и при наличии оснований обжалуйте административно либо в суде.</p><h3>⚠️ Приобретательная давность</h3><p>Навигатор пока не присоединяет автоматически период владения Владельца 1 к периоду Владельца 2 для вывода о приобретательной давности. Этот вопрос требует отдельной правовой оценки.</p>')}
function limpOwner2Docs(){q('Сохранился ли документ, подтверждающий временную регистрацию транспортного средства в ЛНР на Владельца 1?',[['Да, временное свидетельство ЛНР сохранилось',limpOwner2Final],['Свидетельство было изъято, но имеется справка или письменное подтверждение МРЭО',limpOwner2Final],['Документ утрачен или изъят, подтверждения нет, но с Владельцем 1 можно связаться',()=>result('yellow','🟡 НУЖНО ПОДТВЕРДИТЬ ПРЕЖНЮЮ РЕГИСТРАЦИЮ','<p>Получить официальное подтверждение прежней временной регистрации может <b>Владелец 1</b> — лицо, на которое была оформлена временная регистрация ЛНР.</p><p>После подтверждения регистрации можно продолжить маршрут регистрации транспортного средства на Владельца 2 на российский учёт на 5 лет.</p>'+limpArticle()+'<h3>🛑 Если МРЭО отказывает Владельцу 1</h3><p>Нужно получить письменный ответ с конкретным основанием отказа и оценить его обжалование.</p>')],['Документов или подтверждения нет и связаться с Владельцем 1 невозможно',limpOwner2UkraineDocs],['Владелец 1 умер',limpDeadHolder],['Другая ситуация / нет подходящего варианта',()=>other('Л-ИМП.2Б.1')]],'<p>В этой ветке не используем ДКП, договор дарения, доверенность или расписку между Владельцем 1 и Владельцем 2 как основание перехода права собственности.</p>')}
function limpOwner2UkraineDocs(){q('Сохранились ли украинские регистрационные документы на транспортное средство?',[['Да, сохранились',()=>limpOwner2Final('<p><b>Дополнительное обстоятельство:</b> украинские регистрационные документы сохранились и могут дополнительно подтверждать историю транспортного средства.</p>')],['Нет, украинских регистрационных документов нет',()=>limpOwner2Final('<p><b>Дополнительное обстоятельство:</b> украинские регистрационные документы отсутствуют. Это само по себе не исключает пятилетний маршрут, но может усложнить доказывание истории транспортного средства и увеличить риск отказа МРЭО.</p>')],['Другая ситуация / нет подходящего варианта',()=>other('Л-ИМП.2Б.2')]],'<p>ℹ️ Украинские регистрационные документы могут упростить подтверждение истории транспортного средства. Их отсутствие само по себе не означает невозможность регистрации на российский учёт на 5 лет.</p>')}
function limpHolder(){q('На кого была оформлена временная регистрация транспортного средства в ЛНР?',[['На меня — я Владелец 1',limpFirstDate],['На другого человека — я Владелец 2',limpOwner2Docs],['Владелец 1 умер',limpDeadHolder],['Другая ситуация / нет подходящего варианта',()=>other('Л-ИМП.2')]],'<p>Смотрите свидетельство о временной регистрации ЛНР либо официальный документ МРЭО, подтверждающий такую регистрацию.</p>')}
function limpConfirm(){q('Имеется ли документ, подтверждающий прежнюю временную регистрацию транспортного средства в ЛНР?',[['Да, имеется справка или письменный ответ МРЭО',limpHolder],['Нет, письменно в МРЭО ещё не обращался',()=>result('yellow','🟡 СНАЧАЛА ПОДТВЕРДИТЕ ПРЕЖНЮЮ РЕГИСТРАЦИЮ','<p>Обратитесь в МРЭО письменно за сведениями о прежней временной регистрации транспортного средства в ЛНР.</p>'+limpArticle()+'<h3>🛑 Если отказали</h3><p>Получите письменный ответ с основанием отказа. После этого можно определить дальнейший способ защиты.</p>')],['Обращался письменно, но МРЭО отказало',()=>result('yellow','🟡 ПОЛУЧЕН ОТКАЗ МРЭО','<p>Письменный отказ необходимо анализировать по указанному в нём правовому основанию и при наличии оснований обжаловать.</p>'+limpArticle()+'<h3>🛑 Что делать</h3><p>Сохраните заявление и письменный ответ МРЭО. Не ограничивайтесь устными пояснениями сотрудников.</p>')],['В МРЭО сообщили, что сведений о регистрации нет / база отсутствует',()=>result('yellow','🟡 ТРЕБУЕТСЯ ДОПОЛНИТЕЛЬНОЕ ДОКАЗЫВАНИЕ','<p>Отсутствие сведений в имеющейся базе само по себе не используется Навигатором как автоматический вывод о том, что временной регистрации ЛНР не было.</p>'+limpArticle()+'<h3>🛑 Что делать</h3><p>Получите официальный письменный ответ МРЭО и определите дальнейший доказательственный маршрут.</p>')],['Другая ситуация / нет подходящего варианта',()=>other('Л-ИМП.1.1')]])}
function limpDocs(){q('Изымались ли в МРЭО документы временной регистрации ЛНР?',[['Нет, документы временной регистрации ЛНР сохранились',limpHolder],['Да, документы были изъяты в МРЭО',limpConfirm],['Другая ситуация / нет подходящего варианта',()=>other('Л-ИМП.1')]],'<p>ℹ️ Речь именно о <b>свидетельстве временной регистрации ЛНР</b>. Наличие регистрационных знаков ЛНР само по себе в этой ветке не рассматривается как достаточное подтверждение прежней регистрации.</p>')}

function lnrD1(){q('Какая регистрация указана в документах ЛНР?',[['Постоянная регистрация ЛНР',lnrOwner],['Временная регистрация ЛНР на 5 лет (транспортное средство не ввозился из-за рубежа до вхождения ЛНР в состав РФ)',tempLnr],['Временная регистрация ЛНР транспортного средства, ввезённого из-за рубежа до вхождения ЛНР в состав РФ',limpDocs],['Другая ситуация / нет подходящего варианта',()=>other('Л-1')]])}

function ukrOwnResidenceEntry(){q('Можно ли подтвердить выезд с территории нового региона и въезд на территорию Российской Федерации?',[['Да — имеются сведения или документы о пересечении границы, которые могут подтверждаться данными ФТС России',()=>pending('Украина: фактическое проживание подтверждено; имеются сведения о последующем въезде в Российскую Федерацию')],['Да — прямых данных о пересечении границы нет, но имеются документы о последующем систематическом проживании на территории РФ',()=>pending('Украина: фактическое проживание подтверждено; въезд подтверждается совокупностью последующих юридически значимых фактов проживания в Российской Федерации')],['Имеются и сведения о пересечении границы, и документы о последующем проживании в РФ',()=>pending('Украина: имеются сведения о въезде и последующем проживании в Российской Федерации')],['Нет',()=>pending('Украина: требуется индивидуальный анализ доказательств въезда и последующего проживания в Российской Федерации')]],'<p>ℹ️ При отсутствии регистрации по месту жительства эта ветка оценивает не только документы о фактическом проживании в административных границах нового региона, но и сведения о последующем въезде в Российскую Федерацию и проживании после въезда.</p>')}
function ukrResidenceCourtResult(){result('yellow','🟡 НЕОБХОДИМО УСТАНОВИТЬ ФАКТ ПРОЖИВАНИЯ ЧЕРЕЗ СУД','<h3>⚖️ Что означает результат</h3><p>Регистрация по месту жительства («прописка»), подтверждаемая паспортом, отсутствует, но имеются или могут быть собраны иные доказательства фактического проживания на территории нового региона.</p><h3>🚘 Как складывается ситуация на практике</h3><p>По практике МРЭО такие косвенные доказательства — в том числе сведения о пересечении границы, документы о фактическом проживании и другие подтверждения — самостоятельно не принимаются как достаточное подтверждение факта проживания для применения специального порядка регистрации.</p><h3>📋 Что делать</h3><p>Необходимо обратиться в суд с заявлением об установлении юридического факта проживания на территории соответствующего нового региона на юридически значимую дату. Имеющиеся документы, сведения ФТС и иные доказательства фактического проживания могут использоваться как доказательственная база в суде.</p><p>После вступления решения суда в законную силу его можно представить в МРЭО вместе с остальными документами для регистрации транспортного средства.</p><p>Если доказательств пока недостаточно, сначала необходимо собрать и оценить документы, которыми можно подтвердить фактическое проживание для обращения в суд.</p><h3>🛑 Если МРЭО отказало</h3><p>Не ограничивайтесь устным отказом. Получите письменное решение с конкретным правовым основанием. Оно также может иметь значение при определении дальнейшего судебного маршрута.</p><h3>📚 Нормативное основание</h3><p>После официального опубликования постановления Правительства РФ здесь будет указан конкретный пункт или подпункт специального порядка, для применения которого требуется подтверждение территориального условия.</p>')}
function ukrOwnFinal(){result('green','🟢 РЕГИСТРАЦИЯ ТРАНСПОРТНОГО СРЕДСТВА НА РОССИЙСКИЙ УЧЁТ','<h3>⚖️ Что предусматривает специальный порядок</h3><p>По выбранным ответам транспортное средство зарегистрировано на Украине на вас не позднее <b>31 декабря 2025 года</b>, вы являетесь гражданином Российской Федерации и подтверждаете требуемую территориальную связь с новым регионом.</p><h3>📋 Что подготовить</h3><ul><li>паспорт гражданина РФ;</li><li>свидетельство о регистрации транспортного средства Украины;</li><li>имеющиеся государственные регистрационные знаки Украины;</li><li>документ о регистрации по месту жительства на территории нового региона и иные подтверждающие документы — при наличии;</li><li>транспортное средство для осмотра.</li></ul><p>При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>🚘 Как может быть на практике</h3><p>Представьте имеющиеся документы, подтверждающие украинскую регистрацию транспортного средства и территориальное условие. Если МРЭО ставит под сомнение документы или их достаточность, важно получить формальную оценку представленного комплекта документов.</p><h3>🛑 Что делать, если отказали</h3><p>Не ограничивайтесь устным отказом. Подайте документы официально и получите письменное решение МРЭО с конкретным правовым основанием. После этого можно оценить причину отказа и определить способ его обжалования.</p><h3>📚 Нормативное основание</h3><p>Здесь будет указан конкретный пункт или подпункт постановления Правительства РФ о перерегистрации после проверки его окончательной опубликованной редакции.</p>')}
function ukrOwnProofType(){q('Какие документы подтверждают, что на 30 сентября 2022 года вы проживали или были зарегистрированы по месту жительства на территории нового региона?',[['Есть документ о регистрации по месту жительства на территории нового региона',ukrOwnFinal],['Регистрации по месту жительства не было, но есть другие документы, подтверждающие фактическое проживание',ukrResidenceCourtResult],['Есть и регистрация по месту жительства, и другие подтверждающие документы',ukrOwnFinal],['Другая ситуация / нет подходящего варианта',()=>other('У-2А.4')]])}
function ukrOwnProof(){q('Имеются ли у вас документы, подтверждающие, что на 30 сентября 2022 года вы проживали или были зарегистрированы по месту жительства на территории нового региона?',[['Да, имеются',ukrOwnProofType],['Нет',ukrResidenceCourtResult]],'<p>ℹ️ Отсутствие документа на этом этапе не означает автоматический отказ. Дальше Навигатор будет учитывать возможность подтверждения фактического проживания другими допустимыми доказательствами.</p>')}
function ukrOwnRegion(){q('На 30 сентября 2022 года вы проживали или были зарегистрированы по месту жительства на территории одного из новых регионов?',[['Да — на территории нового региона, находившейся под контролем Российской Федерации',ukrOwnCitizen],['Да — на территории нового региона, которая впоследствии была освобождена',ukrOwnCitizen],['Да — на территории нового региона, которая находится под контролем Украины',ukrOwnCitizen],['Нет — на 30 сентября 2022 года не проживал и не был зарегистрирован по месту жительства на территории нового региона',()=>result('red','🔴 СПЕЦИАЛЬНЫЙ ПОРЯДОК РЕГИСТРАЦИИ НЕ ПРИМЕНЯЕТСЯ','<h3>⚖️ Что это означает</h3><p>По выбранным ответам на 30 сентября 2022 года вы <b>не проживали и не были зарегистрированы по месту жительства на территории ДНР, ЛНР, Запорожской или Херсонской области</b>.</p><p>Рассматриваемый специальный порядок не предусматривает регистрацию транспортного средства на российский учёт на лицо, которое не относится к установленной постановлением категории граждан по территориальному признаку.</p><h3>📚 Нормативное основание</h3><p>Постановление устанавливает специальный порядок регистрации для определённых категорий граждан, связанных проживанием с территориями новых регионов. <b>Порядок регистрации по этому специальному механизму транспортного средства на лицо, которое не проживало и не было зарегистрировано по месту жительства на территории новых регионов, постановлением не предусмотрен.</b></p><p>После опубликования окончательной редакции постановления здесь будет уточнена ссылка на конкретный пункт, определяющий круг лиц.</p>')]],'<p>ℹ️ Для целей Навигатора под новыми регионами понимаются ДНР, ЛНР, Запорожская и Херсонская области.</p><p><b>Важно:</b> для целей этой ветки освобождённая территория нового региона и территория нового региона, находящаяся под контролем Украины, рассматриваются одинаково. Сам по себе фактический контроль над территорией не исключает её из рассматриваемого юридического маршрута.</p>')}
function ukrOwnCitizen(){q('Являетесь ли вы гражданином Российской Федерации?',[['Да',ukrOwnProof],['Нет',()=>result('red','🔴 СНАЧАЛА НЕОБХОДИМО ПОЛУЧИТЬ ПАСПОРТ ГРАЖДАНИНА РФ','<h3>⚖️ Что это означает</h3><p>По выбранным ответам транспортное средство зарегистрировано на Украине на вас, однако в настоящее время вы не имеете паспорта гражданина Российской Федерации.</p><p>Для применения рассматриваемого специального порядка необходимо соответствовать установленной постановлением категории граждан.</p><h3>📋 Что необходимо сделать</h3><ol><li><b>Получить паспорт гражданина Российской Федерации.</b></li><li>Подтвердить, что на момент принятия соответствующего нового региона в состав Российской Федерации вы <b>проживали либо были зарегистрированы по месту жительства</b> на территории этого региона.</li><li>После получения паспорта РФ и подтверждения территориального условия повторно пройти эту ветку Навигатора.</li></ol><p>Если регистрация по месту жительства («прописка») подтверждается паспортом, далее используется административный маршрут через МРЭО.</p><p>Если прописки не было, но вы фактически проживали в новом регионе и располагаете иными доказательствами, необходимо установить юридический факт проживания через суд. После вступления решения суда в законную силу его можно представить в МРЭО вместе с остальными документами.</p><h3>📚 Нормативное основание</h3><p>Специальный порядок предусматривает регистрацию для соответствующей категории <b>граждан Российской Федерации</b>, имеющих требуемую территориальную связь с новым регионом. После опубликования окончательной редакции постановления здесь будет указан конкретный пункт или подпункт.</p>')]])}
function ukrOwnDate(){q('Когда транспортное средство было зарегистрировано на Украине на ваше имя?',[['Не позднее 31 декабря 2025 года',ukrOwnRegion],['После 31 декабря 2025 года',()=>result('red','🔴 РЕГИСТРАЦИЯ ПО СПЕЦИАЛЬНОМУ ПОРЯДКУ НЕ ПРЕДУСМОТРЕНА','<p><b>По выбранным ответам транспортное средство зарегистрировано на Украине после 31 декабря 2025 года.</b></p><h3>⚖️ Что предусматривает специальный порядок</h3><p>Рассматриваемый порядок распространяется на транспортные средства, зарегистрированные на территории Украины не позднее 31 декабря 2025 года. Если регистрация транспортного средства произведена позже этой даты, данный специальный порядок регистрации на российский учёт на транспортное средство не распространяется.</p><h3>📋 Что это означает</h3><p>Навигатор не продолжает эту ветку по специальному порядку. Необходимо отдельно определять, существует ли иной законный порядок оформления конкретного транспортного средства.</p><h3>🛑 Если в МРЭО возник спор</h3><p>Устный отказ не является окончательным решением. При необходимости подайте обращение официально и получите письменное решение с указанием правового основания.</p>')]],'<p>ℹ️ Для этой ветки имеет значение предельная дата регистрации транспортного средства на Украине — <b>31 декабря 2025 года</b>.</p>')}

function ukrCustomsContactResult(kind){
  const intro=kind==='temporary'
    ? '<p>При въезде транспортного средства оформлялась декларация на временный ввоз. Сам по себе этот факт не означает окончательный отказ в регистрации, однако перед завершением регистрации необходимо проверить, продолжает ли транспортное средство находиться под таможенным контролем.</p>'
    : '<p>Таможенные документы не были оформлены либо таможенный орган отказался их оформлять. Навигатор не определяет таможенный статус транспортного средства самостоятельно.</p>';
  result('yellow','🟡 ТАМОЖЕННЫЙ СТАТУС ТРАНСПОРТНОГО СРЕДСТВА НЕОБХОДИМО УТОЧНИТЬ',
    intro+
    '<h3>⚖️ Что предусматривает специальный порядок</h3><p>Рассматриваемый специальный порядок регистрации построен для транспортных средств, <b>не находящихся под таможенным контролем</b>. При регистрации сведения о таможенном статусе транспортного средства могут проверяться в рамках взаимодействия МВД и ФТС.</p>'+
    '<h3>🚘 Как может быть на практике</h3><p>На момент разработки Навигатора ещё не сформирована понятная практика МРЭО по таким транспортным средствам. Пока также не установлен понятный практический порядок снятия ранее ввезённых транспортных средств с таможенного контроля именно для последующей регистрации по специальному порядку.</p>'+
    '<h3>📋 Что делать</h3><p>Сначала обратитесь в МРЭО для регистрации транспортного средства по специальному порядку и сообщите об обстоятельствах его ввоза и таможенного оформления.</p><p>Если МРЭО установит, что транспортное средство находится под таможенным контролем либо сведения ФТС препятствуют регистрации, обратитесь в таможенный орган и попросите проверить актуальный таможенный статус транспортного средства и разъяснить порядок снятия его с таможенного контроля для последующей регистрации в МРЭО.</p>'+
    '<p><a href="https://cat.customs.gov.ru/appeal" target="_blank" rel="noopener"><b>Обратиться в Центральную акцизную таможню →</b></a></p>'+
    '<p>После урегулирования таможенного статуса вернитесь к регистрации транспортного средства в МРЭО.</p>'+
    '<h3>📚 Нормативное основание</h3><p>После официального опубликования постановления здесь будет указан точный пункт о применении специального порядка к транспортным средствам, не находящимся под таможенным контролем, а также проверена окончательная формулировка взаимодействия МВД и ФТС.</p>');
}
function ukrCustomsControlledResult(){
  result('yellow','🟡 ТРАНСПОРТНОЕ СРЕДСТВО НАХОДИТСЯ ПОД ТАМОЖЕННЫМ КОНТРОЛЕМ',
    '<h3>⚖️ Что предусматривает специальный порядок</h3><p>Рассматриваемый специальный порядок регистрации построен для транспортных средств, <b>не находящихся под таможенным контролем</b>.</p>'+
    '<h3>📋 Что делать</h3><p>Обратитесь в МРЭО и сообщите, что транспортное средство находится под таможенным контролем. Если это препятствует регистрации, обратитесь в таможенный орган для проверки статуса транспортного средства и разъяснения порядка снятия его с таможенного контроля.</p>'+
    '<p><a href="https://cat.customs.gov.ru/appeal" target="_blank" rel="noopener"><b>Обратиться в Центральную акцизную таможню →</b></a></p>'+
    '<p>После урегулирования таможенного статуса вернитесь к регистрации транспортного средства в МРЭО.</p>');
}
function ukrNoCustomsInfo(){
  q('Таможенный контроль',[['Продолжить →',ukrOwner]],'<p>ℹ️ Если транспортное средство <b>не пересекал таможенный пункт пропуска и в отношении него не совершались таможенные операции</b>, он не должен был попадать под таможенный контроль непосредственно в связи с таким перемещением.</p><p>Навигатор не может проверить фактический таможенный статус конкретного транспортного средства. При обращении за регистрацией МРЭО сможет проверить соответствующие сведения в рамках предусмотренного взаимодействия с ФТС.</p>');
}
function ukrCustomsEntryStatus(){
  q('При въезде транспортного средства через таможню оформлялся ли временный ввоз или транспортное средство ставился под таможенный контроль?',[['Да — оформлялась декларация на временный ввоз транспортного средства',()=>ukrCustomsContactResult('temporary')],['Да — таможня оформляла другие документы и транспортное средство находится под таможенным контролем',ukrCustomsControlledResult],['Нет — временный ввоз не оформлялся и транспортное средство под таможенный контроль не ставился',ukrOwner],['Таможня отказалась оформлять транспортное средство / документы не оформлялись',()=>ukrCustomsContactResult('refused')],['Другая ситуация / нет подходящего варианта',()=>other('У-ТАМ-2')]],'<p>ℹ️ Вспомните, оформляли ли на транспортное средство таможенные документы. Например, <b>пассажирскую таможенную декларацию на временный ввоз транспортного средства</b>, устанавливала ли таможня срок временного ввоза или сообщала ли о необходимости дальнейшего таможенного оформления.</p>');
}
function ukrArrival(){
  q('Каким образом транспортное средство оказался на территории Российской Федерации?',[['Въехал через таможенный пункт пропуска',ukrCustomsEntryStatus],['Въехал через линию разграничения / гуманитарный коридор',ukrNoCustomsInfo],['Транспортное средство находился на территории, которая впоследствии перешла под контроль Российской Федерации',ukrNoCustomsInfo],['Другой вариант / нет подходящего варианта',()=>other('У-ТАМ-1')]],'<p>ℹ️ Этот вопрос нужен только для проверки возможного таможенного контроля. Навигатор не разбирает тонкости таможенного законодательства.</p>');
}
function ukrIntro(){hist.push(ukrIntro);app.innerHTML='<section class="q">'+badge('INFO-УКРАИНА')+'<h2>🇺🇦 Транспортное средство с украинской регистрацией: сначала важно понять одну особенность</h2><p>На территориях новых регионов возникают ситуации с транспортными средствами, которые обычное законодательство изначально не предусматривало.</p><p>Транспортное средство могло остаться на освобождаемой территории, быть зарегистрировано на Украине, перейти к другому владельцу, находиться без части документов или попасть на территорию Российской Федерации спустя несколько лет после сделки. Документы могли быть утрачены, архивы — недоступны, а выполнить отдельные формальные требования иногда объективно невозможно.</p><p>Специальные нормы помогают включать транспорт жителей новых регионов в российское правовое поле, но не всегда охватывают всё многообразие реальных ситуаций. Поэтому конкретный транспортное средство может <b>не укладываться в стандартную административную процедуру регистрации в МРЭО</b>. Это ещё не означает, что у владельца отсутствуют права на транспортное средство или что вопрос невозможно решить.</p><h3>⚖️ Иногда административной процедуры недостаточно</h3><p>Некоторые проблемы относятся уже не только к регистрации, но и к <b>праву собственности на транспортное средство</b>. Может потребоваться установить юридически значимые обстоятельства, подтвердить сделку, наследование, длительное владение либо признать право собственности.</p><p>Тогда вопрос может перейти из административной плоскости в <b>гражданско-правовую</b>, а право на транспортное средство — устанавливаться или защищаться в судебном порядке. Поэтому ответ сотрудника МРЭО <b>«зарегистрировать невозможно» не всегда означает, что законных вариантов больше нет</b>.</p><h3>🛑 Если в МРЭО или таможенном органе отказали</h3><p>Особенно осторожно относитесь к <b>устному отказу</b>. Фразы «не положено», «система не пропускает» или «такие транспортные средства не ставим» сами по себе не заменяют письменного решения по вашей ситуации.</p><ol><li><b>Не ограничивайтесь устным ответом.</b> Подайте документы официально и получите письменное решение с указанием правовых оснований отказа.</li><li><b>Не считайте ситуацию безвыходной до анализа причин отказа.</b></li><li><b>Покажите письменный отказ автоюристу.</b> Его нужно сопоставить с документами и фактическими обстоятельствами.</li><li>При наличии законных оснований <b>решение можно обжаловать</b>. Если спор касается непосредственно права на транспортное средство, может потребоваться обращение в суд.</li></ol><h3>🚗 Для чего нужен этот Навигатор</h3><p>Навигатор последовательно разберёт: <b>откуда прибыл транспортное средство → на каком учёте оно находится → на кого оформлены документы → когда и при каких обстоятельствах возникло владение → какие документы сохранились → какой административный или гражданско-правовой путь может подойти.</b></p><p class="warn"><b>Важно:</b> если готового сценария нет, это <b>не означает невозможность оформления</b>. Ситуация может требовать индивидуального правового анализа.</p><div class="opts"><button id="ukr-go">Продолжить проверку транспортного средства →</button></div><button class="back" id="back">← Назад</button></section>';document.getElementById('ukr-go').onclick=ukrArrival;document.getElementById('back').onclick=()=>{hist.pop();let f=hist.pop();f&&f()}}
function ukrOtherOwnerFiveResultRender(){result('green','🟢 РЕГИСТРАЦИЯ РФ НА ОГРАНИЧЕННЫЙ СРОК 5 ЛЕТ','<p><b>По выбранным ответам транспортное средство подпадает под рассматриваемый маршрут регистрации транспортного средства, находящегося во владении гражданина.</b></p><h3>⚖️ Что предусматривает закон</h3><p>По подпункту «д» проекта постановления транспортное средство регистрируется без выдачи паспорта транспортного средства на бумажном носителе с выдачей регистрационных документов на ограниченный срок 5 лет.</p><p><b>Выдаётся СТС РФ на ограниченный срок 5 лет без права продажи и с запретом на внесение изменений в регистрационные данные, а также государственные регистрационные номерные знаки РФ.</b></p><p>ПТС на бумажном носителе не выдаётся.</p><h3>🚘 Как может быть на практике</h3><p>Необходимо представить имеющиеся документы и последовательно подтвердить обстоятельства владения транспортным средством и территориальное условие. Если дополнительного документа о владении нет либо он оформлен после даты выдачи паспорта РФ, в заявлении указываются реальные обстоятельства приобретения транспортного средства или владения им.</p><h3>📋 Что делать</h3><p>Подготовить документ, удостоверяющий личность, свидетельство о регистрации транспортного средства Украины, имеющийся документ о владении — доверенность, договор лизинга либо иной договор — если он имеется, а также документы, подтверждающие соответствие территориальному условию. Обратиться в регистрационное подразделение для проведения регистрационного действия.</p><h3>🛑 Что делать, если отказали</h3><p>Устный отказ не является окончательным результатом. Подайте документы официально и потребуйте письменное решение с конкретным правовым основанием отказа. После этого можно проверить законность указанного основания и определить порядок обжалования.</p><h3>📚 Нормативное основание</h3><p>Подпункт «д» проекта постановления о специальном порядке регистрации транспортных средств в новых регионах. После официального принятия постановления номер, дата и окончательная редакция нормы должны быть проверены и обновлены в Навигаторе.</p>')}
function ukrOtherOwnerTerritory(){q('На 30 сентября 2022 года вы постоянно проживали на территории одного из новых регионов либо ранее постоянно проживали там и затем выехали в другой субъект Российской Федерации?',[['Да — постоянно проживал на территории нового региона на 30 сентября 2022 года',ukrOtherOwnerFiveResult],['Да — ранее постоянно проживал на территории нового региона и затем выехал в другой субъект Российской Федерации',ukrOtherOwnerFiveResult],['Нет',()=>result('red','🔴 РЕГИСТРАЦИЯ НА 5 ЛЕТ ПО СПЕЦИАЛЬНОМУ ПОРЯДКУ НЕ ПРЕДУСМОТРЕНА','<h3>⚖️ Что предусматривает специальный порядок</h3><p>По выбранным ответам транспортное средство зарегистрировано на Украине на другого человека, а вы рассматриваетесь как его владелец. Однако территориальное условие, необходимое для регистрации такого транспортного средства на ваше имя на ограниченный срок 5 лет, не выполняется.</p><p><b>Поэтому регистрация на ваше имя по рассматриваемому пятилетнему специальному порядку не предусмотрена.</b></p><p>Этот результат относится именно к данному специальному маршруту и сам по себе не означает, что транспортное средство невозможно зарегистрировать каким-либо иным законным способом.</p><h3>🛑 Что делать, если возник спор</h3><p>Не ограничивайтесь устным отказом. Подайте документы официально и получите письменное решение МРЭО с конкретным правовым основанием. После этого можно оценить указанное основание и возможный дальнейший правовой маршрут.</p><h3>📚 Нормативное основание</h3><p>Здесь будет указан конкретный пункт или подпункт постановления Правительства РФ о перерегистрации после проверки его окончательной опубликованной редакции.</p>')]],'<p>ℹ️ Нынешнее проживание в другом регионе России само по себе не исключает этот маршрут. Для пятилетней регистрации по рассматриваемому основанию важно соответствовать территориальному условию проекта постановления.</p>')}
function ukrOtherOwnerStatement(){q('Укажите обстоятельства, при которых транспортное средство перешло в ваше владение',[['Понятно — продолжить',ukrOtherOwnerTerritory]],'<p>ℹ️ При регистрации транспортного средства на российский учёт на ограниченный срок 5 лет необходимо <b>в заявлении в МРЭО о регистрационном действии</b> описать, <b>где, когда, от кого и при каких обстоятельствах вы приобрели транспортное средство либо получили его во владение</b>. Эти сведения указываются в заявлении, подаваемом при регистрации, а не вводятся в Навигатор.</p><p>Опишите <b>где, когда, от кого и при каких обстоятельствах транспортное средство было передано вам</b>. Например: транспортное средство было передано по устной договорённости о покупке, стороны фактически исполнили договорённость — транспортное средство, ключи и регистрационные документы были переданы покупателю, однако надлежащее оформление перехода права собственности по украинским регистрационным правилам произведено не было.</p><p>Само по себе отсутствие оформленного договора не означает, что обстоятельства владения нельзя изложить в заявлении. Важно описывать <b>только реальные факты</b>, а не подбирать формулировку под желаемый результат.</p><p>Если обстоятельства приобретения или владения транспортным средством в заявлении не указать, не будет выполнено требование специального порядка, предусматривающее указание таких сведений при отсутствии соответствующего документа. Это может стать основанием для отказа МРЭО в регистрации.</p>')}
function ukrOtherOwnerNoDoc(){ukrOtherOwnerStatement()}
function ukrOtherOwnerDocDate(doc){q('Когда был оформлен документ, на основании которого транспортное средство находится в вашем владении?',[['До даты выдачи мне паспорта гражданина Российской Федерации и не позднее 31 декабря 2025 года',ukrOtherOwnerTerritory],['После даты выдачи мне паспорта гражданина Российской Федерации',ukrOtherOwnerStatement]],'<p>ℹ️ Наличие документа, соответствующего указанному сроку, является способом подтверждения владения, но <b>не изменяет регистрационный режим</b>: при выполнении остальных условий эта ветка ведёт к регистрации на ограниченный срок 5 лет.</p><p>Если документ оформлен после даты выдачи паспорта РФ, для этой ветки используются сведения владельца в заявлении об обстоятельствах приобретения транспортного средства (владения транспортным средством).</p>')}
function ukrDeceasedHeirBuyerFinalRender(){result('green','🟢 РЕГИСТРАЦИЯ ТРАНСПОРТНОГО СРЕДСТВА НА ПРИОБРЕТАТЕЛЯ НА РОССИЙСКИЙ УЧЁТ','<h3>⚖️ Что предусматривает специальный порядок</h3><p>Транспортное средство было зарегистрировано на Украине не позднее <b>31 декабря 2025 года</b>. Право на транспортное средство после смерти зарегистрированного собственника подтверждено <b>свидетельством о праве на наследство</b>, а наследник передаёт транспортное средство приобретателю по <b>договору купли-продажи или договору дарения</b>. Приобретатель соответствует территориальному условию специального порядка.</p><h3>📋 Что подготовить</h3><ul><li>свидетельство о регистрации транспортного средства Украины;</li><li>свидетельство о праве на наследство;</li><li>договор купли-продажи или договор дарения между наследником и приобретателем;</li><li><b>паспорт гражданина РФ наследника (продавца/дарителя);</b></li><li>паспорт гражданина РФ приобретателя;</li><li>документы, подтверждающие постоянное проживание приобретателя на территории нового региона на соответствующую дату;</li><li>транспортное средство для осмотра.</li></ul><p>При успешной регистрации приобретателю выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>🚘 Как может быть на практике</h3><p>Поскольку в украинском свидетельстве указан умерший собственник, необходимо показать МРЭО непрерывную юридическую цепочку перехода права:</p><p><b>умерший собственник → свидетельство о праве на наследство → наследник → ДКП/дарение → приобретатель.</b></p><h3>🛑 Если МРЭО отказывает</h3><p>Не ограничивайтесь устным отказом. Представьте документы официально и получите письменное решение с конкретным правовым основанием отказа. После этого можно оценить законность отказа и способ его обжалования.</p>')}
function ukrDeceasedHeirBuyerEntry(){q('Можно ли подтвердить выезд с территории нового региона и въезд на территорию Российской Федерации?',[['Да — имеются сведения или документы о пересечении границы, которые могут подтверждаться данными ФТС России',ukrDeceasedHeirBuyerFinal],['Да — прямых данных о пересечении границы нет, но имеются документы о последующем систематическом проживании на территории РФ',ukrDeceasedHeirBuyerFinal],['Имеются и сведения о пересечении границы, и документы о последующем проживании в РФ',ukrDeceasedHeirBuyerFinal],['Нет',()=>pending('Украина: требуется индивидуальный анализ доказательств выезда, въезда и последующего проживания приобретателя')]],'<p>ℹ️ При отсутствии регистрации по месту жительства Навигатор учитывает документы о фактическом проживании в новом регионе и сведения о последующем въезде и проживании в Российской Федерации.</p>')}
function ukrDeceasedHeirBuyerProofType(){q('Какие документы подтверждают, что на 30 сентября 2022 года вы проживали или были зарегистрированы по месту жительства на территории нового региона?',[['Есть документ о регистрации по месту жительства на территории нового региона',ukrDeceasedHeirBuyerFinal],['Регистрации по месту жительства не было, но есть другие документы, подтверждающие фактическое проживание',ukrResidenceCourtResult],['Есть и регистрация по месту жительства, и другие подтверждающие документы',ukrDeceasedHeirBuyerFinal],['Другая ситуация / нет подходящего варианта',()=>other('У-3.5')]])}
function ukrDeceasedHeirBuyerProof(){q('Имеются ли у вас документы, подтверждающие, что на 30 сентября 2022 года вы проживали или были зарегистрированы по месту жительства на территории нового региона?',[['Да, имеются',ukrDeceasedHeirBuyerProofType],['Нет',ukrResidenceCourtResult]],'<p>ℹ️ Отсутствие подтверждающего документа на этом этапе не означает автоматический отказ. Требуется определить, какими допустимыми доказательствами можно подтвердить территориальное условие.</p>')}
function ukrDeceasedHeirBuyerTerritory(){q('На 30 сентября 2022 года вы проживали или были зарегистрированы по месту жительства на территории одного из новых регионов?',[['Да — проживал на территории нового региона',ukrDeceasedHeirBuyerProof],['Да — был зарегистрирован по месту жительства на территории нового региона',ukrDeceasedHeirBuyerProof],['Да — проживал и был зарегистрирован по месту жительства',ukrDeceasedHeirBuyerProof],['Нет — не проживал и не был зарегистрирован по месту жительства',()=>result('red','🔴 СПЕЦИАЛЬНЫЙ ПОРЯДОК ДЛЯ ПРИОБРЕТАТЕЛЯ НЕ ПРИМЕНЯЕТСЯ','<p>По выбранным ответам приобретатель транспортного средства по договору купли-продажи или дарения на 30 сентября 2022 года не проживал и не был зарегистрирован по месту жительства на территории нового региона.</p><p>Регистрация транспортного средства на этого приобретателя по рассматриваемому специальному порядку не предусмотрена.</p>')]],'<p>ℹ️ Для этой ветки учитывается территориальная связь именно приобретателя транспортного средства. Нынешнее место проживания само по себе не определяет результат.</p>')}
function ukrDeceasedHeirTransferBasis(){q('Как планируется оформить переход права собственности на транспортное средство от наследника к вам?',[['Договор купли-продажи',ukrDeceasedHeirBuyerTerritory],['Договор дарения',ukrDeceasedHeirBuyerTerritory],['Другая ситуация / нет подходящего варианта',()=>other('У-3.3')]])}
function ukrDeceasedOtherHeirFinalRender(){result('green','🟢 РЕГИСТРАЦИЯ ТРАНСПОРТНОГО СРЕДСТВА НЕПОСРЕДСТВЕННО НА НАСЛЕДНИКА','<h3>⚖️ Что предусматривает специальный порядок</h3><p>Транспортное средство зарегистрировано на Украине не позднее <b>31 декабря 2025 года</b> на умершего собственника. Право наследника на транспортное средство подтверждается <b>свидетельством о праве на наследство</b>. Наследник соответствует территориальному условию специального порядка.</p><h3>📋 Что подготовить</h3><ul><li>паспорт гражданина РФ наследника;</li><li>свидетельство о праве на наследство на транспортное средство;</li><li>свидетельство о регистрации транспортного средства Украины;</li><li>документ, подтверждающий смерть прежнего собственника — <b>при наличии</b>;</li><li>имеющиеся государственные регистрационные знаки Украины;</li><li>документы, подтверждающие проживание или регистрацию наследника по месту жительства на территории нового региона;</li><li>транспортное средство для осмотра.</li></ul><p>При успешной регистрации наследнику выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>🚘 Как может быть на практике</h3><p>Из документов должна прослеживаться последовательная цепочка:</p><p><b>собственник по украинскому свидетельству → смерть собственника → наследование → наследник.</b></p><h3>📚 Нормативное основание</h3><p>Здесь будет указан конкретный пункт или подпункт постановления Правительства РФ о перерегистрации после проверки его окончательной опубликованной редакции.</p><h3>🛑 Если отказали</h3><p>Не ограничивайтесь устным отказом. Подайте документы официально и получите письменное решение МРЭО с конкретным правовым основанием. После этого можно оценить причину отказа и определить способ его обжалования.</p>')}
function ukrDeceasedOtherHeirEntry(){q('Можно ли подтвердить выезд наследника с территории нового региона и въезд на территорию Российской Федерации?',[['Да — имеются сведения или документы о пересечении границы, которые могут подтверждаться данными ФТС России',ukrDeceasedOtherHeirFinal],['Да — прямых данных о пересечении границы нет, но имеются документы о последующем систематическом проживании наследника на территории РФ',ukrDeceasedOtherHeirFinal],['Имеются и сведения о пересечении границы, и документы о последующем проживании наследника в РФ',ukrDeceasedOtherHeirFinal],['Нет',()=>pending('Украина: требуется индивидуальный анализ доказательств выезда, въезда и последующего проживания наследника')]],'<p>ℹ️ При отсутствии регистрации по месту жительства учитываются документы о фактическом проживании наследника в новом регионе и сведения о последующем въезде и проживании в Российской Федерации.</p>')}
function ukrDeceasedOtherHeirProofType(){q('Какие документы подтверждают, что на 30 сентября 2022 года наследник проживал или был зарегистрирован по месту жительства на территории нового региона?',[['Есть документ о регистрации наследника по месту жительства на территории нового региона',ukrDeceasedOtherHeirFinal],['Регистрации по месту жительства не было, но есть другие документы, подтверждающие фактическое проживание наследника',ukrResidenceCourtResult],['Есть и регистрация по месту жительства, и другие подтверждающие документы',ukrDeceasedOtherHeirFinal],['Другая ситуация / нет подходящего варианта',()=>other('У-3.ДН.3')]])}
function ukrDeceasedOtherHeirProof(){q('Имеются ли документы, подтверждающие, что на 30 сентября 2022 года наследник проживал или был зарегистрирован по месту жительства на территории нового региона?',[['Да, имеются',ukrDeceasedOtherHeirProofType],['Нет',ukrResidenceCourtResult]],'<p>ℹ️ Отсутствие подтверждающего документа на этом этапе не означает автоматический отказ. Требуется определить, какими допустимыми доказательствами можно подтвердить территориальное условие наследника.</p>')}
function ukrDeceasedOtherHeirTerritory(){q('На 30 сентября 2022 года наследник проживал или был зарегистрирован по месту жительства на территории одного из новых регионов?',[['Да — проживал на территории нового региона',ukrDeceasedOtherHeirProof],['Да — был зарегистрирован по месту жительства на территории нового региона',ukrDeceasedOtherHeirProof],['Да — проживал и был зарегистрирован по месту жительства',ukrDeceasedOtherHeirProof],['Нет — не проживал и не был зарегистрирован по месту жительства',()=>result('red','🔴 СПЕЦИАЛЬНЫЙ ПОРЯДОК ДЛЯ НАСЛЕДНИКА НЕ ПРИМЕНЯЕТСЯ','<p>Свидетельство о праве на наследство подтверждает право наследника на транспортное средство, однако для регистрации транспортного средства с украинского учёта по рассматриваемому специальному порядку требуется территориальная связь наследника с новым регионом.</p><p>По выбранным ответам на 30 сентября 2022 года наследник не проживал и не был зарегистрирован по месту жительства на территории нового региона. Поэтому регистрация транспортного средства непосредственно на этого наследника по рассматриваемому специальному порядку не предусмотрена.</p><h3>🛑 Если возник спор в МРЭО</h3><p>Не ограничивайтесь устным отказом. Подайте документы официально и получите письменное решение с конкретным правовым основанием.</p>')]],'<p>ℹ️ Поскольку транспортное средство планируется зарегистрировать непосредственно на наследника, территориальное условие проверяется именно в отношении наследника.</p>')}
function ukrDeceasedHeirGoal(){q('Что планируется сделать с транспортным средством?',[['Зарегистрировать транспортное средство на наследника',ukrDeceasedOtherHeirTerritory],['Оформить транспортное средство на меня с участием наследника',ukrDeceasedHeirTransferBasis]])}
function ukrDeceasedAbsentHeirTerritory(){q('На 30 сентября 2022 года вы постоянно проживали на территории одного из новых регионов либо ранее постоянно проживали там и затем выехали в другой субъект Российской Федерации?',[['Да — постоянно проживал на территории нового региона на 30 сентября 2022 года',ukrOtherOwnerFiveResult],['Да — ранее постоянно проживал на территории нового региона и затем выехал в другой субъект Российской Федерации',ukrOtherOwnerFiveResult],['Нет',()=>result('red','🔴 ПЯТИЛЕТНИЙ СПЕЦИАЛЬНЫЙ ПОРЯДОК НЕ ПРИМЕНЯЕТСЯ','<p>По выбранным ответам территориальное условие для регистрации транспортного средства на фактического владельца на ограниченный срок 5 лет не подтверждается.</p><p>Регистрация транспортного средства на вас по рассматриваемому пятилетнему специальному порядку не предусмотрена.</p><h3>🛑 Если возник спор в МРЭО</h3><p>Не ограничивайтесь устным отказом. Подайте документы официально и получите письменное решение с конкретным правовым основанием.</p>')]],'<p>ℹ️ Поскольку пятилетняя регистрация рассматривается на ваше имя, территориальное условие проверяется именно в отношении вас, а не наследника.</p>')}
function ukrDeceasedAbsentHeirPossession(){q('Транспортное средство фактически находится в вашем владении?',[['Да, транспортное средство находится у меня',ukrDeceasedAbsentHeirTerritory],['Нет',()=>pending('Украина: транспортное средство не находится во владении пользователя — пятилетняя регистрация на пользователя по этой ветке не формируется')]],'<p>ℹ️ Если наследник не может лично присутствовать в МРЭО, Навигатор не предлагает регистрацию через представителя по доверенности. При фактическом владении транспортным средством рассматривается регистрация на ваше имя на ограниченный срок 5 лет с указанием в заявлении реальных обстоятельств приобретения транспортного средства или владения им.</p>')}
function ukrDeceasedHeirPresence(){q('Может ли наследник, указанный в свидетельстве о праве на наследство, лично присутствовать в МРЭО при регистрации транспортного средства?',[['Да, может присутствовать',ukrDeceasedHeirGoal],['Нет, присутствовать не может',ukrDeceasedAbsentHeirPossession]])}
function ukrDeceasedPossession(){q('Транспортное средство фактически находится в вашем владении и пользовании?',[['Да',ukrDeceasedPossessionBasis],['Нет',()=>pending('Украина: транспортное средство умершего собственника не находится во владении заявителя — пятилетний маршрут фактического владельца по этой ветке не формируется')]])}
function ukrDeceasedPossessionBasis(){q('На каком основании транспортное средство находится в вашем владении?',[['Доверенность',()=>ukrDeceasedPossessionDocDate('доверенность')],['Договор лизинга',()=>ukrDeceasedPossessionDocDate('договор лизинга')],['Иной договор',()=>ukrDeceasedPossessionDocDate('иной договор')],['Дополнительного документа о владении нет',ukrDeceasedPossessionStatement],['Другая ситуация / нет подходящего варианта',()=>other('У-3.2')]],'<p>ℹ️ Для пятилетнего маршрута проверяется основание владения транспортным средством. При отсутствии дополнительного документа используются сведения владельца в заявлении об обстоятельствах приобретения транспортного средства (владения транспортным средством).</p>')}
function ukrDeceasedPossessionDocDate(doc){q('Когда был оформлен документ, на основании которого транспортное средство находится в вашем владении?',[['До даты выдачи мне паспорта гражданина Российской Федерации и не позднее 31 декабря 2025 года',ukrDeceasedPossessionTerritory],['После даты выдачи мне паспорта гражданина Российской Федерации',ukrDeceasedPossessionStatement]],'<p>ℹ️ Наличие документа, соответствующего указанному сроку, подтверждает владение, но не изменяет регистрационный режим: при выполнении остальных условий маршрут ведёт к регистрации на ограниченный срок 5 лет.</p><p>Если документ оформлен после даты выдачи паспорта РФ, используются сведения владельца в заявлении об обстоятельствах приобретения транспортного средства (владения транспортным средством).</p>')}
function ukrDeceasedPossessionStatement(){q('Укажите обстоятельства, при которых транспортное средство перешло в ваше владение',[['Понятно — продолжить',ukrDeceasedPossessionTerritory]],'<p>ℹ️ Для регистрации транспортного средства на 5 лет необходимо указать в заявлении реальные обстоятельства его приобретения или владения им.</p><p>Опишите <b>когда, от кого и при каких обстоятельствах транспортное средство было передано вам</b>. Например: транспортное средство было передано по устной договорённости о покупке, стороны фактически исполнили договорённость — транспортное средство, ключи и регистрационные документы были переданы вам, однако надлежащее оформление перехода права собственности по украинским регистрационным правилам произведено не было.</p><p>Само по себе отсутствие оформленного договора не означает, что обстоятельства владения нельзя изложить в заявлении. Важно описывать <b>только реальные факты</b>, а не подбирать формулировку под желаемый результат.</p><p>Если обстоятельства приобретения или владения транспортным средством в заявлении не указать, не будет выполнено требование специального порядка, предусматривающее указание таких сведений при отсутствии соответствующего документа. Это может стать основанием для отказа МРЭО в регистрации.</p>')}
